pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in stream, tighter packing matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if next_item_size < post_residual {
            let nr = post_residual as f64;
            let ratio = next_item_size as f64 / nr;
