            score -= 25.0 * ratio * (1.0 - (nr - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving large dead space
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * waste * (0.5 + progress);
        }
    } else {
        // last item: prefer minimal residual
        score += 0.0;
    }

    // Relative to mean residual: placing into a bin with residual near mean
    // balances bin pool; extreme bins get slight normalization.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        score = 45.0 + 55.0 * tightness - 10.0 * open_pressure;
