pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tightness of fit: reward small post_residual relative to capacity.
    let tight = post_residual as f64 / cap;
    score += tight * tight * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: chained-fit quality when the next item fits the leftover.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 6.0 + 4.0 * (1.0 - progress) + 6.0 * chain_fill;
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // Dead space the next item cannot use; penalize proportionally,
            // but scaled by how much of the bin this placement already fills.
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            if waste > 0.05 * cap {
                // Deeper stream: dead space matters more since fewer chances to recover.
                score += (0.08 + 0.05 * progress) * waste;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize bins whose residual is already small (fragmented bins) unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 5.0 * res_frac * (1.0 - tight);

    // Global state coupling: slack everywhere -> mildly discourage filling this bin
    // unless it is a good fit; sharpen with a quadratic term on mean residual.
    let mr_frac = mean_residual / cap;
    score += (0.03 * mean_residual + 20.0 * mr_frac * mr_frac * cap) * (1.0 - tight);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * tight;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, slightly higher to force compaction.
        score += 16.0;
        // In early stream with few bins, opening is cheaper.
        score -= 6.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is rarely worth it.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Single fitting bin: compare its likely leftover against a fresh bin.
        if fitting_bins_count == 1 {
            score -= 4.0;
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 2.0;
            }
        }
        // Lookahead: an empty bin gives maximal flexibility for a next item
        // that is large relative to this one, or exactly complements it.
        if next_item_size > 0 {
            if next_item_size as f64 > 0.5 * cap {
                score -= 4.0;
            }
            // A fresh bin of full capacity can host the next item alone;
            // if the next item is huge, preserve emptiness.
            if next_item_size as f64 > 0.75 * cap {
                score -= 3.0;
            }
        }
    }

    score
}

