            score += 12.0;
        } else {
            score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
        // Exact two-item pairing bonus.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    } else {
        // Last item: close bins aggressively.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Fragmentation-aware: if mean residual across bins is large, prefer
    // consolidating into existing bins rather than opening new ones.
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing bins are crowded (low mean residual) or many bins already open.
    if bin_residual == bin_capacity {
        let crowding = 1.0 - mean_residual / bin_capacity as f64;
        let phase = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 * (1.0 - crowding) + 20.0 * (1.0 - phase);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Slight preference for fuller bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth in [0,1])
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / cap;

    // Non-linear polynomial coupling: dead space becomes more costly as stream progresses
    // and as it becomes more "wasted" (small relative to typical item sizes).
    let waste_penalty = (pr * pr) * (1.0 + progress * (pr * (1.0 - pr)) * 4.0);
    score += waste_penalty * cap * 0.5;

    // Reward tight fits: item filling most of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fill * fill) * cap * 0.4;

    // Scarcity pressure: if few bins can fit the item, favor using them (penalize new bins implicitly)
    if fitting_bins_count >= 1 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= scarcity * cap * 0.3;
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    }

    // Lookahead coupling: penalize leaving a residual that neither fits nor is well-used
    // relative to the next item, via smooth polynomial interaction.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if (post_residual as f64) >= nxt { 1.0 } else { 0.0 };
        let gap = (post_residual as f64 - nxt).abs() / cap;
        // Smooth mismatch penalty: large gaps (wasted) or just-missed fits are bad
        let mismatch = gap * gap * (1.0 - fit_next * 0.5);
        score += mismatch * cap * (0.5 + 0.5 * progress);
        // Reward exact-ish chaining: post residual close to next item size
        score -= (1.0 - gap) * fit_next * cap * 0.3;
    }

    // Mean-residual coupling: penalize bins whose residual deviates badly from the fleet mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.2;

    // Mild pressure against accumulating many open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // New-bin candidate: make an empty bin moderately attractive only early in the stream
    // or when the item barely fits any open bin; smooth via progress polynomial.
    if bin_residual == bin_capacity {
        let early_bias = (1.0 - progress) * (1.0 - progress);
        score += cap * (0.6 - 0.5 * early_bias);
        if fitting_bins_count <= 1 {
            score -= cap * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (integer division into size classes) ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional residual class: how many "quarter capacity" slots remain
    let quarter_class = post_residual / (bin_capacity / 4).max(1);
    let quarter_penalty = match quarter_class {
        0 => -6.0,              // near-perfect fill: reward strongly
        1 => -1.5,              // small usable slot
        2 => 0.5,               // mid: mild penalty
        _ => 0.0,
    };
    score += quarter_penalty;

    // Modulo-10 dead-space detector: residuals not divisible by 10 are harder to fill
    // with items drawn on a 1..100 grid; penalize awkward remainders.
    let rem = post_residual % 10;
    if post_residual > 0 {
        score += (rem as f64) * 0.15; // small penalty for awkward residue
        if rem == 0 {
            score -= 2.0; // clean divisible residual: reward
        }
    }

    // Zero post-residual = perfect closure, big reward
    if post_residual == 0 {
        score -= 12.0;
    }

    // --- Next-item lookahead: can the next item fit into post_residual? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item chains into this bin: strong reward
        score -= 4.0 + (next_item_size as f64) * 0.02;
        // Extra reward if chain closes the bin exactly after two placements
        if post_residual - next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space: next item cannot use the leftover
        let waste_frac = pr / c;
        score += waste_frac * 5.0;
    }

    // --- Tight-fit bonus: item fills most of the residual ---
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    if fill_ratio > 0.8 {
        score -= 3.0 * fill_ratio;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits: avoid opening a new bin unless residual waste is huge
        score -= 5.0;
        if post_residual < 10 {
            score -= 4.0; // closing it out is great
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost. Prefer it only when current bins are badly fragmented.
        let fragmentation = mean_residual / c;
        score = 20.0 - fragmentation * 8.0;
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 3.0;
        // If no open bin fits, new bin is attractive
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Large next item favors a fresh bin
        if next_item_size >= 60 {
            score -= 3.0;
        }
    }

    // --- Mean residual coupling: bins far from mean are penalized (keep pool homogeneous) ---
    let dev = (pr - mean_residual).abs();
    score += dev * 0.03;

    // --- Open bins pressure: many open bins -> favor filling existing ones ---
    score += (open_bins_count as f64) * 0.4;

    // --- Harmonic size-class matching: item_size mod 20 classes ---
    let item_class = item_size % 20;
    if item_class == 0 {
        // Round items pack cleanly into round residuals
        if post_residual % 20 == 0 {
            score -= 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Gaps below 10 are pure waste (min item size is 10 in classic streams;
    // for unknown distributions treat gaps < 12 as near-dead).
    if post_residual < 12 {
        score -= 60.0; // near-perfect fit, strongly reward
    } else if post_residual < 25 {
        score -= 25.0; // decent fit
    } else {
        // penalize large unusable residuals super-linearly
        score += 0.35 * (post_residual as f64 - 25.0);
    }

    // Exact-fill jackpot
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling: if the next item fits exactly into the post residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this bin's leftover: leftover likely dead space
        score += 0.25 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize opening new bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when few bins open or item huge
        score += 15.0 + 3.0 * pressure;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // reward using existing bins more when many are open
        score -= 0.5 * pressure.min(10.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual context: if this bin's post residual is far below the
    // mean residual, we are compacting well.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be slightly more willing to open bins (build a
    // diverse residual pool); later, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
