        score += 14.0;
        // In early stream with few bins, opening is cheaper.
        score -= 6.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is rarely worth it.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // If only one bin fits and its residual is tiny, opening may be better.
        if fitting_bins_count == 1 {
            score -= 4.0;
        }
        // Lookahead: an empty bin gives maximal flexibility for the next item.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: post_residual as dead-space cost, mildly super-linear.
    let pr = post_residual as f64;
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more.
    let coupling = (pr / cap) * (1.0 - progress) * (progress * progress);
    score -= 12.0 * coupling;

    // Penalize residuals that are too small to ever be useful (smooth term).
    let unusable = (1.0 - (pr / cap).min(1.0)).exp() * (pr / cap).exp();
    score += 8.0 * unusable * (0.5 + 0.5 * progress);

    // Last-chance bonus: only one fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: if next item fits into post_residual, reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 + 4.0 * progress;
    }

    // Mild preference for using already-open bins vs opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 3.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 1.0;
    }

    // Smooth tie-break: prefer bins with residual close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes is reusable.
    let pr = post_residual;
    if pr > 0 {
        // Class bonus: post_residual in "nice" residue classes (multiples of 10, 20, 25, 50)
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 3.0; }
        if pr % 50 == 0 { harmonic_bonus += 3.0; }
        // Exact-fill class: post_residual 0 is perfect
        if pr == 0 { harmonic_bonus += 40.0; }
        score -= harmonic_bonus;

        // Dead-space penalty: post_residual below the minimum item size is wasted
        if pr < 10 {
            score += 25.0;
        } else {
            // Small awkward leftover: penalize via integer-division threshold classes
            let class = pr / 10; // 1..=9 harmonic class
            score += (9 - class as i64).max(0) as f64 * 1.5;
        }
    }

    // Lookahead coupling: does post_residual accommodate the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 30.0; // perfect two-item chain
            } else if slack % 10 == 0 {
                score -= 8.0;
            } else if slack < 10 {
                score += 10.0; // leaves dead space after next item
            }
        } else {
            // Next item won't fit here anyway; prefer larger post_residual for it
            score += 3.0;
        }
    } else {
        // Last item: minimize waste entirely
        score += 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive if item is huge relative to residual
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        if pressure > 0.7 {
            score -= 15.0 * (pressure - 0.7) / 0.3;
        } else {
            score += 12.0 * (0.7 - pressure) / 0.7;
        }
        // Early in stream, opening bins builds a portfolio of residuals
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 && item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits proportionally: filling most of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a very small gap elsewhere; moderate standing penalty.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 70 {
            score -= 6.0;
        }
        if post_residual < 10 && post_residual > 0 {
            score -= 10.0; // large item nearly fills a fresh bin: acceptable
        }
    }

    // Open-bin pressure: mildly discourage scattering across many bins.
    score += (open_bins_count as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Dead-space alignment with mean residual: avoid leaving gaps similar to mean
    // residual (wasted capacity pattern).
    if post_residual as f64 > mean_residual * 0.9 && post_residual > 0 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit post_residual but could fit other residual, small penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // Early stream: be more conservative about tight fills to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 3.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and the next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-match_gap / 8.0).exp();
        // Penalize residuals that are too small to fit the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful bin choice).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Mild tightening as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1), used to modulate exploration vs. consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill of this bin before placement.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Reward tight fits: squared penalty on post-residual makes small leftovers very attractive.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward bins that become nearly full after this placement (perfect-fit bonus).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward if next item exactly consumes the remaining space.
            if post_residual - next_item_size <= 5 {
                score -= 10.0;
            }
        } else {
            // Penalize leaving post-residual that the next item cannot use
            // but which is large enough to be "wasted dead space".
            let dead = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
            score += 0.3 * dead;
        }
    }

    // Penalize placing into bins far below the mean residual (keeps a pool of large bins
    // available for large future items), stronger early in the stream.
    let mean_dev = mean_residual - bin_residual as f64;
    score += 0.15 * mean_dev * (1.5 - progress);

    // Reward filling already-well-used bins (fill momentum), scaled by stream progress.
    score -= 10.0 * fill * (0.5 + progress);

    // When many bins are open, prefer consolidation into existing bins;
    // when few are open, allow more freedom.
    let openness = (open_bins_count as f64).ln_1p();
    score += 3.0 * openness * (1.0 - fill);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable only when no open bin fits well.
        // Penalize new bins when decent alternatives exist.
        if fitting_bins_count > 0 {
            let best_possible_leftover = open_bins_count; // placeholder scale
            let _ = best_possible_leftover;
            // Estimate: if any open bin leaves small post-residual, discourage new bin.
            // We approximate using mean residual: if mean residual >= item_size, open bins are roomy.
            if mean_residual >= item_size as f64 {
                score += 30.0 + 10.0 * (fitting_bins_count as f64);
            } else {
                score += 10.0;
            }
        }
        // If this is the only option (fitting_bins_count==1 refers to this empty bin),
        // keep score moderate so it can win.
        score += 5.0;
    }

    // Mild stochastic-free tie-breaker: prefer bins with slightly larger residuals
    // among equals (keeps small holes from fragmenting).
    score += 0.01 * bin_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: penalize wasted space, super-linearly
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Stream-progress coupling: early on, prefer tight fits mildly; late, waste less tolerable
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward near-perfect fills (post_residual small relative to item)
    score -= 20.0 * (1.0 - post_norm).powi(6) * (0.5 + fit_ratio);

    // Dead-space penalty: residual that no plausible item can use
    let next_fit = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
    score -= 15.0 * next_fit;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Crowd penalty: many open bins with slack -> prefer consolidating into fuller bins
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 0.5 * crowd * post_norm;

    // New-bin candidate: make empty bin moderately attractive only when current item is large
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * progress) - 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact divisions of capacity are "sweet spots".
    let pr = post_residual;
    if pr > 0 {
        // Residuals that divide capacity cleanly are reusable -> reward.
        if cap as u32 % pr == 0 {
            score -= 6.0;
        }
        // Class by residue modulo common item sizes (harmonic classes).
        let m10 = (pr % 10) as f64;
        score -= 2.0 * (10.0 - m10) / 10.0; // prefer residuals aligned to decile grid
        if pr % 5 == 0 {
            score -= 1.5;
        }
        // Dead-space penalty: tiny unusable fragments
        if pr < 10 {
            score += (10 - pr) as f64 * 1.2;
        }
    } else {
        score -= 8.0; // perfect fill
    }

    // Lookahead coupling: does post_residual admit next item in harmonic terms?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 3.0;
            if (pr - next_item_size) % 10 == 0 {
                score -= 2.0; // leaves decile-aligned residue again
            }
            if slack < 10.0 {
                score += slack * 0.5; // near-miss leaves fragment
            }
        } else {
            // next item cannot fit here regardless; slight bonus for using big space now
            score -= (next_item_size - pr).min(20) as f64 * 0.15;
        }
    }

    // Capacity-fraction thresholds on post_residual
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 2.0; // bin still half-full, keep it attractive
    } else if frac < 0.2 {
        score += 2.0; // creating sparse remainder
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Late in stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.5 * progress); // new-bin candidate penalty
        if post_residual as f64 / cap > 0.5 && next_item_size > 0 && next_item_size <= pr {
            score -= 4.0; // big item opening a fresh bin is fine
        }
    }

    // Tie-break toward bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead space penalties
    if post_residual < 10 {
        score += 60.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 8.0;
    }

    // Lookahead compatibility
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem == 0 {
                score -= 45.0;
            } else if rem % 10 == 0 {
                score -= 18.0;
            } else if rem < 10 {
                score += 10.0;
            } else {
                score -= 6.0;
            }
        } else {
            score += post_frac * 12.0;
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic like the champion)
    let tight = post_frac;
    score += tight * tight * 30.0;
    score -= (item_size as f64 / cap) * 10.0;

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * (1.0 - tight);
    }

    // New-bin candidate: strongly discourage unless nothing fits well
    if bin_residual == bin_capacity {
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let best_existing_small = mean_residual < item_size as f64 * 0.5;
        let fresh_cost = 30.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 18.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0
            - 25.0 * poor_options
            - if best_existing_small { 10.0 } else { 0.0 };
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to capacity.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: preserve a useful pair for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (1.0 - progress);
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += 0.05 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += 5.0 * res_frac * (1.0 - tight);

    score += 0.03 * mean_residual * (1.0 - tight);

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * tight;
    }

    // NEW MUTATION: chain-fit lookahead. If after placing the item, the next item
    // AND a following mid-size item could both fit, this bin is a valuable chain
    // anchor; reward proportionally to how much slack remains for a second item.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 1 {
            // Slack that could host a second future item: reward moderately,
            // scaled down late in the stream when future items are less certain.
            score -= 2.0 * (after_next as f64 / bin_capacity as f64) * (1.0 - 0.5 * progress);
        }
    }

    // NEW MUTATION: waste-anticipation penalty. If the post residual is nonzero
    // but smaller than the next item (guaranteed dead space), penalize more
    // strongly when the dead space is a large fraction of the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = post_residual as f64 / next_item_size as f64;
        score += 3.0 * dead_frac;
    }

    // NEW MUTATION: fragment-risk guard. When the residual after placement is
    // very small but nonzero (orphan fragment), penalize lightly unless it is a
    // perfect fit, since such fragments rarely get reused.
    if post_residual > 0 && post_residual < item_size {
        score += 1.5 * (1.0 - post_residual as f64 / item_size.max(1) as f64);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 14.0;
        score -= 6.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        if fitting_bins_count == 1 {
            score -= 4.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0;
        }
        // NEW MUTATION: if the best existing fit leaves a large dead residual
        // (post_residual high relative to next item), opening a fresh bin is
        // more attractive. Approximate via mean residual as a proxy for how
        // poor existing fits are.
        if next_item_size > 0 && mean_residual > next_item_size as f64 * 1.5 {
            score -= 5.0;
        }
        // NEW MUTATION: late in the stream, avoid opening bins aggressively
        // since remaining items cannot amortize the new bin.
        if progress > 0.75 {
            score += 8.0 * (progress - 0.75) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = post_residual as f64 / bin_capacity as f64;

    // Tightness of fit: reward small post_residual relative to capacity.
    score += tight * tight * 32.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 28.0;
    }

    // Lookahead: if the next item can fit into the post residual, this placement
    // preserves a useful pair; reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 7.0 + 5.0 * (1.0 - progress);
            if post_residual == next_item_size {
                score -= 9.0;
            }
        } else {
            // Dead space the next item cannot use: penalize proportionally,
            // scaled by how large the unusable chunk is relative to capacity.
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += 0.09 * waste * (1.0 + tight);
        }
