        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }

        // Single fitting bin: weigh the flexibility of a fresh bin against the
        // near-fit. If the current item is small relative to capacity, a fresh
        // bin paired with the next item may pack better.
