                score -= 8.0;
            }
        } else {
            // Dead space the next item cannot use; penalize proportionally,
            // with a sharper threshold to catch medium-sized waste too.
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            if waste > 0.03 * cap {
                score += 0.10 * waste;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize bins whose residual is already small (fragmented bins) unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 5.0 * res_frac * (1.0 - tight);

    // Global state coupling: high mean residual means slack everywhere; discourage
    // filling this bin unless it is a good fit, scaled by stream progress.
    score += 0.03 * mean_residual * (1.0 - tight) * (1.0 + 0.5 * progress);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * tight;
    }

    // Waste-budget guard: penalize leaving residuals in the awkward middle zone
    // (too big for typical small items, too small for medium ones), which is the
    // dominant source of dead space. Zone tuned around capacity fractions.
    if post_residual > 0 {
        let pr = post_residual as f64 / cap;
        if pr > 0.25 && pr < 0.55 {
            score += 4.0 * (1.0 - (pr - 0.25).abs() / 0.30);
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 14.0;
        // In early stream with few bins, opening is cheaper.
        score -= 6.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is rarely worth it.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        if fitting_bins_count == 1 {
            score -= 4.0;
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 2.0;
            }
        }
        // Lookahead: an empty bin gives maximal flexibility for a next item that
        // is large relative to this one.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            score -= 5.0;
        }
        // High mean residual across open bins signals poor consolidation so far;
        // opening a fresh bin then compounds fragmentation, so penalize it.
        if mean_residual > 0.3 * cap {
            score += 3.0 * (mean_residual / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = post - nxt;
            // Perfect follow-up fit bonus
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 { score -= 10.0; }
        } else {
            // Post-residual too small for next item: penalize dead space, worse if close-but-fail
            let miss = nxt - post;
            score += 6.0 + 8.0 * (miss / nxt.max(1.0) as f64).min(1.0);
        }
    } else {
        // Last item: just prefer tightest fit
        score += 0.0;
    }

    // Penalize large post-residual relative to mean residual (wasteful placement)
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item would fit perfectly in the fresh bin after this one, soften
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
