    let cap = bin_capacity as f64;

    // Tightness of fit: reward small post_residual relative to capacity (sharpened).
    let tight = post_residual as f64 / cap;
    score += tight * tight * 45.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 32.0;
    }

    // Lookahead: chained-fit quality when the next item fits the leftover.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 7.0 + 4.0 * (1.0 - progress) + 9.0 * chain_fill;
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            if waste > 0.04 * cap {
                score += (0.12 + 0.06 * progress) * waste;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 16.0 + 8.0 * progress;
    }

    // Penalize fragmented bins unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 7.0 * res_frac * (1.0 - tight);

    // Global state coupling: slack everywhere -> discourage filling this bin
    // unless it is a good fit; quadratic term sharpens the effect.
    let mr_frac = mean_residual / cap;
    score += (0.03 * mean_residual + 24.0 * mr_frac * mr_frac * cap) * (1.0 - tight);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.5 * tight;
    }

    // Pair-completion bonus: next item exactly equals current item and fills bin.
    if next_item_size == item_size && post_residual == item_size {
        score -= 10.0;
    }

    // Near-perfect fit bonus: residual smaller than 5% of capacity.
    if post_residual > 0 && (post_residual as f64) < 0.05 * cap {
        score -= 7.0;
    }

    // Dead space: residual too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.18 * post_residual as f64;
    }

