    // meaningful (below 10% of capacity) but nonzero wastes the bin; reward
    // leaving it slightly larger instead.
    if post_residual > 0 && (post_residual as f64) < 0.10 * cap && post_residual < next_item_size {
        score -= 4.0;
    }

    // NEW: exact-fill anticipation — if residual before placement equals the
    // next item, placing this item elsewhere and saving the bin is valuable;
    // conversely, if post_residual exactly equals next item, it is a perfect chain.
    if bin_residual == next_item_size && next_item_size > 0 {
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: higher to force compaction.
        score += 24.0;
        // In early stream with few bins, opening is cheaper.
        score -= 5.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is rarely worth it.
        if fitting_bins_count > 1 {
            score += 14.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Single fitting bin: opening may preserve flexibility, but only if the
        // next item is large enough to benefit from a fresh bin.
        if fitting_bins_count == 1 {
            score -= 3.0;
            if next_item_size > 0 && next_item_size as f64 > 0.6 * cap {
                score -= 3.0;
            }
        }
        // Lookahead: preserve emptiness for a huge next item.
        if next_item_size > 0 {
            if next_item_size as f64 > 0.5 * cap {
                score -= 4.0;
            }
            if next_item_size as f64 > 0.75 * cap {
                score -= 3.0;
            }
            // A fresh bin can pair items of the same size.
            if next_item_size == item_size {
                score -= 2.0;
            }
        }
        // If mean residual across open bins is large, existing bins have
        // plenty of slack; opening a new bin wastes that slack.
        if mean_residual > 0.35 * cap {
            score += 7.0 * (mean_residual / cap - 0.35);
        }
        // Late in the stream, avoid opening new bins unless forced.
        if progress > 0.8 {
            score += 9.0 * (progress - 0.8);
        }
        // NEW: if the only fitting bin leaves a large residual while a fresh
        // bin would leave exactly the item size, opening is competitive.
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size == item_size {
            score -= 2.0;
        }
    }

    score
}

