        score -= 8.0;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            if rem == 0 {
                score -= 50.0;
            } else if rem % 10 == 0 {
                score -= 18.0 + 6.0 * chain_fill;
            } else if rem < 10 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
        } else {
            // Dead space the next item cannot use; penalize proportionally
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.08 * waste;
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic)
    let tight = post_frac;
    score += tight * tight * 30.0;
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.0 * res_frac * (1.0 - tight);

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * (1.0 - tight);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // New-bin candidate: strongly discourage unless nothing fits well
    if bin_residual == bin_capacity {
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let best_existing_small = mean_residual < item_size as f64 * 0.5;
        let mut fresh_cost = 34.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 16.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0
            - 25.0 * poor_options
            - if best_existing_small { 12.0 } else { 0.0 };
        // If only one bin fits and it is nearly full, a fresh bin preserves flexibility
        if fitting_bins_count == 1 {
            fresh_cost -= 6.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
        }
        // Empty bin gives maximal flexibility for a large next item
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 5.0;
        }
        // Late stream: consolidation matters more, raise opening cost
        if progress > 0.7 {
            fresh_cost += 8.0 * (progress - 0.7);
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Two-step lookahead: prefer leftovers that can host next item AND leave a
    // harmonic remainder (multiple of 10) for the item after that.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 && rem2 % 10 == 0 {
            score -= 3.0 + 3.0 * (1.0 - progress);
        }
    }

    // Reward near-exact consumption of large residuals (compaction of open bins)
    if post_residual > 0 && post_frac < 0.05 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (1..=100) can use
    // are worthless; penalize them super-linearly.
    if post_residual > 0 {
        // A residual is "dead" if it is smaller than the minimum item size (1),
        // but practically small gaps (<~10) attract nothing in typical streams.
        // Penalize any residual that is smaller than the NEXT item (can't chain),
        // and penalize very small residuals harshly.
        if post_residual < next_item_size.max(1) {
            score += (post_residual as f64) * 2.0 + 5.0;
        }
        if post_residual < 10 {
            score += 15.0;
        }
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // (penalize the new-bin candidate, which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
        // But if no open bin fits well, opening may be justified; soften when
        // this item is huge relative to capacity.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    // (chaining placement).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mild alignment with mean residual: prefer bins whose post_residual stays
    // near the mean (keeps a balanced portfolio of gap sizes).
    score += ((post_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 5.0;

    // Late in the stream, consolidate: slightly stronger preference for existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= 3.0 * progress;
        }
    }

    score
}

