    }

    // Penalize bins whose residual is already small (fragmented) unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 5.0 * res_frac * (1.0 - tight);

    // Global state coupling: high mean residual means slack everywhere.
    score += 0.03 * mean_residual * (1.0 - tight);

