    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * (1.0 - norm_pr);
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate: only open when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
