    if post_residual > 0 && post_residual < 10 {
        score += 0.8 * (10 - post_residual) as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * open_pressure * (0.5 + progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a scarce small hole — use it.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (mean_residual - resid_f) / mean_residual;
        if deviation > 0.0 {
            score -= 8.0 * deviation.min(1.0);
        } else {
            score += 3.0 * (-deviation).min(1.0);
        }
