    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 25.0 * large_item_bonus - 10.0 * progress;
        // If no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Small residual bins are precious: the smaller the residual (that still fits), the better.
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    score
}

