                score += 0.08 * waste;
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic)
    let tight = post_frac;
    score += tight * tight * 30.0;
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.0 * res_frac * (1.0 - tight);

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * (1.0 - tight);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // NEW: reward placements that leave a residual matching common item sizes
    // (divisible by 5), which future items are more likely to fill exactly.
    if post_residual >= 5 && post_residual % 5 == 0 && post_residual != bin_residual {
        score -= 3.0 + 2.0 * (1.0 - progress);
    }

    // NEW: penalize leaving residuals just below typical small-item sizes
    // (wasted slivers that no small item can use).
    if post_residual >= 1 && post_residual <= 3 {
        score += 8.0;
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut fresh_cost = 34.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 16.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 25.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 6.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 14.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 5.0;
        }
        // NEW: when the item is small and many bins fit it, opening is wasteful.
        if item_size <= 20 && fitting_bins_count >= 2 {
            fresh_cost += 10.0;
        }
        // NEW: late in the stream, prefer closing bins tightly; opening is costlier.
        fresh_cost += 6.0 * progress;
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Core: prefer small post_residual (best-fit), with a non-linear
    // polynomial shaping of the residual so very tight fits are
    // strongly rewarded and dead space is penalized super-linearly.
    let x = (pr / cap).clamp(0.0, 1.0);
    let mut score = pr * (1.0 + 0.8 * x * x + 0.6 * x * x * x * x);

    // Smooth stream-progress coupling: early in the stream, be more
    // tolerant of residual (keep bins flexible); late in the stream,
    // push hard toward tight packing.
    let progress_tilt = 0.5 + 1.5 * progress;
    score *= 0.7 + 0.5 * progress_tilt;

    // Interaction: residual waste vs. mean residual across open bins.
    // A bin whose post_residual sits far below the mean residual is
    // harmonically packed (good); far above the mean is fragmentation.
    let frag = (pr - mean_residual).abs() / (cap + 1.0);
    score += 25.0 * frag * frag * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly
    // encourage using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 - progress);
    }

    // Lookahead: if the next item would fit exactly into the resulting
    // residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // New-bin candidate: make it moderately attractive only when it
    // beats fragmentation, i.e. keep its score near its raw residual
    // plus a mild opening cost that shrinks as the stream progresses.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
