        if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            if rem == 0 {
                score -= 60.0;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 10 {
