    score += 0.03 * mean_residual * (1.0 - tight);

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut fresh_cost = 36.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 16.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 28.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 8.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            // Lone fit with a large residual: fresh bin keeps room for the
            // big next item instead of fragmenting the only usable bin.
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 16.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 6.0;
        }
        // Late stream: fresh bins are more expensive since remaining items are few.
        fresh_cost += 6.0 * progress;
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: raw post residual dominates, plus superlinear tightness pressure.
    let mut score = pr + norm_pr * norm_pr * (25.0 + 10.0 * progress);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Polynomial coupling: late in the stream, dead space is increasingly costly.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;

    // Reward bins whose residual is near the item size (perfect fill).
    let fill = item_size as f64 / cap;
    score -= 2.0 * fill * (1.0 - fill);

    // Lookahead: chained-fit quality in the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) <= post_residual {
            let chain_fill = next_item_size as f64 / pr;
            score -= 6.0 + 4.0 * (1.0 - progress) + 6.0 * chain_fill;
            if next_item_size as f64 == pr {
                score -= 8.0;
            }
        } else {
            // Dead space the next item cannot use: penalize if truly wasted.
            let waste = pr - next_item_size as f64;
            if waste > 0.05 * cap {
                score += 0.08 * waste;
            }
        }
    }

    // Penalize deviating far from the mean residual (homogeneous pool).
    score += 0.5 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // Consolidation pressure when many bins are open.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * (1.0 - norm_pr);
    }

    // New-bin candidate: only open when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 14.0 - 6.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        } else if fitting_bins_count == 1 {
            score -= 4.0;
            if next_item_size >= item_size {
                score -= 2.0;
            }
        }
        // Empty bin preserves flexibility for a large next item.
        if next_item_size as f64 > 0.5 * cap {
            score -= 4.0;
        }
        // Large items prefer fresh bins.
        score -= 2.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets of width 10.
    // Small residuals are "dead space" — reward placements that leave
    // residuals in well-structured classes (near 0 or near multiples of 10).
    let post_class = (post_residual / 10) as f64;
    let post_mod = (post_residual % 10) as f64;

    // Penalize residuals in awkward interior classes (1..9 mod 10 hard to fill),
    // reward exact harmonic classes (mod == 0).
    score += (post_mod / 10.0) * 8.0;
    score -= post_class * 2.0;

    // Strong reward for near-perfect fit (post_residual small).
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: excellent chaining, especially if it's a tight chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
            // Harmonic bonus: chained residual stays in a clean class.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: penalize mildly, more if residual is wasted.
            let waste = next_item_size as f64 - post_residual as f64;
            score += waste * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 40.0;
        // But if many bins are open with large mean residual, prefer consolidation.
        score += mean_residual * 0.5;
        // Early in stream, opening bins is cheaper; later, pack tighter.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // If next item is huge and nothing fits it later, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 10.0;
        }
        // If only one fitting bin exists and it's tight, allow opening.
        if fitting_bins_count == 1 && item_size >= 60 {
            score -= 35.0;
        }
    }

    // Mild preference for fuller bins (smaller bin_residual) overall.
    score += (bin_residual as f64) * 0.05;

    // Encourage using bins when many are open (avoid bin explosion).
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to capacity.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Near-perfect fit: residual that is too small for even the smallest
    // plausible future item is essentially "dead" — reward such compaction
    // (residual < 8 is nearly unusable) to reduce dead space ratio.
    if post_residual > 0 && post_residual < 8 {
        score -= 10.0;
    } else if post_residual >= 8 {
        // Usable leftover: scale its value by how likely a future item fits.
        let usable_frac = post_residual as f64 / bin_capacity as f64;
