        score += 4.0 * usable_frac;
    }

    // Lookahead: if the next item can fit into the post residual, this placement
    // preserves a useful pair; reward it, scaled by chained-fit quality.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 6.0 + 4.0 * (1.0 - progress) + 6.0 * chain_fill;
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // Dead space the next item cannot use; penalize proportionally.
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            let cap_frac = bin_capacity as f64;
            // Sharper threshold: dead space above 4% of capacity is waste.
            if waste > 0.04 * cap_frac {
                score += 0.10 * waste;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize bins whose residual is already small (fragmented) unless fit is tight.
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += 5.0 * res_frac * (1.0 - tight);

    // Global state coupling: high mean residual means slack everywhere; mildly
