        // If only one bin fits, compare its wasted leftover against a fresh bin.
        if fitting_bins_count == 1 {
            score -= 4.0;
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 2.0;
            }
        }
        // Lookahead: an empty bin gives maximal flexibility for a large next item.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 4.0;
        }
        // Extra penalty for opening a new bin late in the stream: fewer chances
        // remain to fill it, so consolidation matters more.
        score += 6.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
