        if mean_residual > 50.0 {
            score -= 25.0;
        }
    }

    // Progress-based calibration: late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

