        // Lookahead: fresh bin preserves flexibility for a large next item.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            score -= 4.0;
        }
        // NEW: when the item is small relative to capacity and the stream is
        // early, a fresh bin keeps large contiguous space; make opening mildly
        // more attractive so we don't shred big residuals with tiny items.
        let item_frac = item_size as f64 / cap;
        if item_frac < 0.2 && progress < 0.5 {
