        }
        // NEW: late in the stream, avoid opening bins unless nothing else fits
        // well; raise the cost to force compaction into existing bins.
        if progress > 0.7 {
            score += 4.0 * (progress - 0.7) / 0.3;
        }
    }

    // NEW: mild extra reward when this placement leaves a residual exactly
    // matching a common small-item size bucket (1-10), improving chained fills.
    if post_residual > 0 && post_residual <= 10 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in the stream, be frugal with open bins;
    // later, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
