    }
    // Near-perfect lookahead: next item fits leaving minimal waste.
    else if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 25.0 - 2.0 * gap; // strong reward for tight two-item packing
        } else {
            score -= 5.0 / gap; // weak reward for loose but feasible chaining
        }
    }
    // Next item cannot follow: penalize leaving a residual that is unusable
    // for typical small items (dead space).
    else if next_item_size > 0 && post_residual < next_item_size {
        if post_residual < 10 {
            score += 15.0; // tiny dead space penalty
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: choosing a bin with residual below mean
    // means we shrink the "tight" bins first, preserving larger residuals.
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.2;
    }

    // Penalize opening a new bin, more so early in the stream and when
    // open bins already exist.
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 40.0 * (1.0 - progress);
        let crowding = if open_bins_count > 0 { open_bins_count as f64 * 2.0 } else { 0.0 };
        score += open_penalty + crowding;
    } else {
        // Reward using existing bins, scaled by how crowded the pool is.
        score -= 3.0 + open_bins_count as f64 * 0.5;
    }

    // Late-stream consolidation: favor filling bins nearly completely.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0 * (0.5 + progress);

    // Slight penalty proportional to wasted residual relative to item size,
    // discouraging placements that leave more slack than the item itself.
    if residual_f > item_size as f64 * 2.0 {
        score += (residual_f - item_size as f64 * 2.0) * 0.1;
    }

    score
}

