            score -= 3.0 * pair_fill * (1.0 - progress);
        }
    }

    // NEW: residual-band shaping. Bins whose residual falls into awkward mid
    // bands (hard to fill with typical items) are slightly deprioritized when
    // a tighter alternative exists; very small residuals are cheap to keep.
    let res_band = (bin_residual as f64 / (cap * 0.25)).floor();
    if res_band >= 1.0 && res_band <= 2.0 && tight > 0.05 {
        score += 2.5 * (1.0 - tight);
