        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            score -= 4.0;
        }
        // NEW: when mean residual across open bins is very low, the stream is
        // nearly done consolidating; a fresh bin preserves that tightness.
        if mean_residual < 0.1 * cap && fitting_bins_count <= 2 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
