            }
            // Lone fit with a large residual: fresh bin keeps room for the
            // big next item instead of fragmenting the only usable bin.
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 16.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 6.0;
        }
        // Late stream: fresh bins are more expensive since remaining items are few.
        fresh_cost += 6.0 * progress;
        // If the mean residual across open bins can comfortably host the next
        // item, a fresh bin is less necessary; if mean residual is tight,
        // opening a fresh bin preserves flexibility.
        if next_item_size > 0 {
            if mean_residual >= next_item_size as f64 {
                fresh_cost += 5.0;
            } else {
                fresh_cost -= 3.0;
            }
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Combined coupling: prefer placements that both tighten this bin and
    // leave a residual the next item can chain into; penalize mid-range
    // leftovers that are too small for typical follow-ups but too large to
    // count as dead space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        if rem > 0 && rem < 5 && tight > 0.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into harmonic bands.
    // Residuals in the lowest band (<= 10) are near-perfect fits -> strong reward.
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / capacity_f; // fraction of capacity wasted after placement

    // Harmonic class index: 0 = tiny residual (great), 3 = large residual (bad)
    let class = if post_residual == 0 { 0 }
        else if post_residual <= bin_capacity / 10 { 1 }
        else if post_residual <= bin_capacity / 4 { 2 }
        else if post_residual <= bin_capacity / 2 { 3 }
        else { 4 };

    // Reward deep fits, scaled by class depth
    let class_penalty = match class {
        0 => -60.0,
        1 => -25.0,
        2 => 0.0,
        3 => 15.0,
        _ => 30.0,
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals that are nice multiples
    // (divisible by common item granularities) are reusable -> reward.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional to leftover after next item
            let two_step_waste = (post_residual - next_item_size) as f64;
            score += two_step_waste * 0.3;
            if post_residual - next_item_size <= bin_capacity / 10 {
                score -= 12.0; // two-item near-perfect chain
            }
        } else {
            // next item cannot use this residual: penalize residual more
            score += frac * 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // early in stream, opening bins is cheap (need supply)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // if nothing fits well anywhere (large mean residual spread), allow new bin
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // if next item is huge and residuals are small, new bin attractive
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // mild penalty for many open bins to discourage bin proliferation
        score += open_bins_count as f64 * 0.5;
        // prefer bins whose residual is close to mean (balance)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Integer-division threshold: post_residual >= half capacity means half-empty bin
    if post_residual >= bin_capacity / 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tightness of fit: reward small post_residual relative to capacity.
    let tight = post_residual as f64 / cap;
    score += tight * tight * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: chained-fit quality, refined with a sharper exact-fit reward.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 6.0 + 4.0 * (1.0 - progress) + 7.0 * chain_fill;
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Dead space the next item cannot use; penalize quadratically so
            // large unusable leftovers are strongly avoided.
            let waste = post_residual as f64;
            if waste > 0.05 * cap {
                let w = waste / cap;
                score += 30.0 * w * w + 0.05 * waste;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Fragmentation penalty: penalize bins with large residual unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 5.0 * res_frac * (1.0 - tight);

    // Global slack coupling.
    score += 0.03 * mean_residual * (1.0 - tight);

    // Consolidation pressure when many bins are open.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * tight;
    }

    // New-bin candidate handling: open a fresh bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, slightly higher to resist bin inflation.
        score += 16.0;
        // Early stream: opening is cheaper.
        score -= 6.0 * (1.0 - progress);
        // Many fitting bins: opening a new bin is rarely worth it.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Single fit: weigh the quality of that lone fit against a fresh bin.
        if fitting_bins_count == 1 {
            score -= 4.0;
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 2.0;
            }
        }
        // Lookahead: fresh bin preserves flexibility for a large next item.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            score -= 5.0;
        }
        // Mid-stream: with high mean residual across bins, prefer consolidation.
        if mean_residual > 0.25 * cap && progress > 0.15 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

