            // sharpened: scale by waste fraction of capacity rather than raw size,
            // so large-capacity bins with big holes are punished harder.
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            let waste_frac = waste / cap;
            if waste_frac > 0.05 {
                score += 8.0 * waste_frac + 0.05 * waste;
            }
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize bins whose residual is already small (fragmented bins) unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 5.0 * res_frac * (1.0 - tight);

    // Global state coupling: slack everywhere -> mildly discourage filling unless tight.
    score += 0.03 * mean_residual * (1.0 - tight);

    // Many open bins: encourage consolidation.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * tight;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 14.0;
        // In early stream with few bins, opening is cheaper.
        score -= 6.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is rarely worth it.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // If only one bin fits: a tiny residual there means a near-perfect fit exists;
        // a large residual means opening preserves flexibility. Compare the item's
        // fill ratio against the fresh-bin alternative.
        if fitting_bins_count == 1 {
            let fill = item_size as f64 / cap;
            // Small items: prefer squeezing into the lone fitting bin.
            score -= 4.0 + 6.0 * (1.0 - fill);
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 2.0;
            }
