}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavily penalize
    }
    // Small-but-usable gaps are also risky if nothing fits them next.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (low post_residual relative to bin capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin; if not, penalize leaving a gap the next
    // item cannot use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items
    // thin; consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when the current item is small
    // relative to capacity or existing bins are nearly full (high mean fill).
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        // Opening a new bin is good if existing bins are mostly full.
        score += mean_fill * 0.2;
        // Penalize new bins more as open bins accumulate.
        score += open_bins_count as f64 * 2.0;
        // A new bin leaves residual = capacity - item_size; that baseline
        // is already in score; add a fixed opening cost.
        score += 8.0;
        // But if the item is large, a fresh bin is a natural home.
        score -= item_size as f64 * 0.15;
    }

    // Mild tie-break: prefer bins with less residual overall (fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

