        if fitting_bins_count >= 2 && mean_residual < 0.15 * cap {
            fresh_cost += 7.0 * (1.0 - progress);
        }
        fresh_cost += 8.0 * progress;
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_frac = post_residual as f64 / cap;
    let tight = post_frac;

    // Perfect / near-perfect fit tiers (sharpened dead-space handling).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 22.0;
    } else if post_residual < 8 {
        score -= 8.0;
    } else if post_residual < 15 {
        score += 10.0 - post_frac * 20.0;
    } else if post_residual < 25 {
        score += 5.0;
    }

    // Exact-fill anticipation: item exactly consumes the bin's residual.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 80.0;
    }
    // Near-exact fill graded bonus.
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Tightness of fit: quadratic sharpening.
    score += tight * tight * 38.0;
    score -= (item_size as f64 / cap) * 8.0;

    // Lookahead: chained-fill quality.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            if rem == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 5 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Dead space: leftover too small for the next item.
            let dead = post_frac < 0.12 && (next_item_size as f64) > post_residual as f64 * 2.0;
            score += post_frac * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.12 * post_residual as f64;
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 26.0 + 12.0 * progress;
