    // Penalize fragmented bins unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 5.0 * res_frac * (1.0 - tight);

    // Global slack coupling.
    let mr_frac = mean_residual / cap;
    score += (0.03 * mean_residual + 18.0 * mr_frac * mr_frac * cap) * (1.0 - tight);

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0 * tight;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Residual-band matching: prefer bins whose residual is close to item size.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
    }

    // NEW: waste-ratio term — penalize placements whose post-residual is unusable
    // (smaller than the smallest plausible item) more aggressively mid-stream.
    if post_residual > 0 {
        let unusable = post_residual < 6;
        if unusable {
            score -= 4.0 * (1.0 - progress); // reward sealing bins with tiny leftovers early
        }
        // Penalize leaving a residual that is just barely too small for the next item
        // (worst kind of dead space: it blocks the chain but is nonzero).
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            let block = (next_item_size - post_residual) as f64;
