        // Reward residuals that can host a mid-range item after this placement.
        if next_item_size > 0 && post_residual >= next_item_size + 6 {
            score -= 2.0 * (post_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
