        // a fresh bin becomes relatively more attractive.
        let best_gap_frac = mean_residual / cap;
        if fitting_bins_count >= 2 && best_gap_frac > 0.5 {
            fresh_cost -= 4.0 * (best_gap_frac - 0.5);
