        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        // NEW: mid-stream, if the item would leave a residual that is too
        // small for the next item yet too large to be "waste-free", a fresh
        // bin preserves the existing residual for the upcoming item. This
        // complements the late-stream guard with a smoother, earlier gate.
