            && progress > 0.35
            && next_item_size > 0
            && post_residual > 0
            && post_residual < next_item_size
            && post_residual > next_item_size / 2
        {
            fresh_cost -= 4.0 * progress * (post_residual as f64) / (next_item_size as f64);
