        // Early-stream fresh bins are expensive.
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        // Fresh bin cheaper when the item nearly fills it exactly.
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        // Fresh bin cheaper when few bins fit and mean residual is high.
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        // Fresh bin cheaper for large items late in the stream.
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        // Fresh bin cheaper when no existing fit is near-tight.
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        // Fresh bin cheaper when next item is large and would strand existing residuals.
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        // Fresh bin expensive when many open bins have small residuals that
        // this item could compact (avoid premature bin creation).
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        // NEW: fresh bin cheaper when the best existing fit leaves a stranded
        // residual that nothing upcoming can use (dead-space escape hatch).
        if fitting_bins_count >= 1 && post_residual >= 10
            && next_item_size > post_residual
            && (next_item_size as f64) > mean_residual * 1.2 {
            fresh_cost -= 4.0 + 3.0 * progress;
        }
        // NEW: fresh bin more expensive when the item is small — small items
        // should almost always compact into existing residual space.
        if fill < 0.25 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.25 - fill) * 10.0;
        }
        score += fresh_cost;
    }

    score
}

