    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size as u32 {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Penalize "dead zone" residuals unusable by upcoming items.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // NEW: dead-space ratio pressure — penalize bins whose post_residual
    // fraction exceeds the item's fill fraction (asymmetric waste shaping).
    if bin_residual < bin_capacity && norm_pr > fill * 0.5 {
        score += 3.5 * (norm_pr - fill * 0.5) * (0.5 + progress);
    }

    // NEW: reward bins whose post_residual matches a "harmonious" band
    // that commonly appears from small items (residual recycling bands).
    if post_residual >= 1 && post_residual <= 25 && next_item_size > 0 {
        let band = post_residual % 10;
        if band <= 2 && post_residual >= next_item_size {
            score -= 2.5 * (1.0 - progress);
        }
    }

    // NEW: fragmentation index — count how poorly the leftover decomposes
    // relative to next_item_size; large awkward leftovers get pushed down.
    if next_item_size > 0 && post_residual > next_item_size {
        let waste = post_residual % next_item_size.max(1);
        if waste > 0 && waste < 3 {
            score -= 2.0;
        } else if waste > next_item_size / 2 {
            score += 1.5 * progress;
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size as u32 {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        // NEW: fresh bin cheaper when total slack across open bins cannot
        // plausibly absorb this plus the next item (global slack check).
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let total_slack = mean_residual * (open_bins_count as f64);
            if total_slack < (item_size + next_item_size) as f64 {
                fresh_cost -= 8.0;
            }
        }
        // NEW: fresh bin expensive early when the item is small — small items
        // should almost always compact into existing residual space.
        if fill < 0.3 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.3 - fill) * 10.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead space penalties (finer tiers)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score += 40.0 - post_frac * 30.0;
    } else if post_residual < 10 {
        score += 30.0 - post_frac * 25.0;
    } else if post_residual < 20 {
        score += 14.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else if bin_residual < bin_capacity {
        // Absolute dead-space penalty scaled by stream position (from best)
        score += 0.06 * (post_residual - 30) as f64 * (0.4 + 0.6 * progress);
    }

    // Exact-fill anticipation (from best heuristic)
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = post_frac < 0.12 && (next_item_size as f64) > post_residual as f64 * 2.0;
            score += post_frac * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.08 * post_residual as f64;
        }
        // Two-step lookahead: near-filling leftovers
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < post_residual as f64 && post_residual as f64 - nr <= 6.0 {
            score -= 4.5 * (1.0 - (post_residual as f64 - nr) / 6.0) * (1.0 - progress);
        }
        // Conserve low residuals for future small items
        if post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic, progress-sharpened)
    let tight = post_frac;
    score += tight * tight * (36.0 + 20.0 * progress);
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - tight);

    // Residual-band gap shaping (from best heuristic)
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * tight;
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Divisibility-aware multi-reuse reward (from best heuristic)
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone residual penalty: too big to waste, too small for upcoming items
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let next_large = next_item_size as f64 > 0.5 * cap;
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + fill * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if next_large {
            fresh_cost -= 7.0;
        }
        // Late stream: fresh bins more expensive since few items remain
        fresh_cost += 8.0 * progress;
        // Early stream: fresh bins extra expensive
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        // Fresh bin cheaper when item nearly fills it exactly
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        // Fresh bin cheaper when best existing fit would leave a large unusable gap
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        // Fresh bin cheaper when no existing fit is near-tight
        if fitting_bins_count >= 1 && post_frac > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (post_frac - 0.3) * 10.0;
        }
        // Fresh bin expensive when many open bins have small residuals this item could compact
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
