        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        // Fresh bin expensive when many open bins have small residuals to compact.
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        // NEW: fresh bin cheaper mid-stream when item is mid-sized and all fits
        // leave residuals in the awkward 8..20 dead zone.
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        // NEW: fresh bin expensive when existing bins are near-perfect fits
        // (tight-packing regime — keep compacting instead of expanding).
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight-fit base with progress sharpening.
    score += norm_pr * norm_pr * (30.0 + 10.0 * progress);
    score -= fill * 12.0;

    // Dead-space tiers.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 22.0;
    } else if post_residual < 7 {
        score -= 8.0;
    } else if post_residual < 14 {
        score += 12.0 - norm_pr * 30.0;
    }

    // Exact and near-exact fit anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        if gap <= 3.0 {
            score -= 16.0 - 4.0 * gap;
        }
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Harmonic leftovers.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 9.0;
    }

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if nr == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = nr / pr;
            if rem == 0 {
                score -= 25.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 18.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Multi-reuse divisibility bonus.
            let k = post_residual / next_item_size;
            if k >= 2 {
                score -= 2.5 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
            }
        } else {
            let dead = norm_pr < 0.12 && nr > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        // Conserve low residuals for future small items.
        if post_residual < next_item_size {
            score += 4.0;
        }
        // Dead-zone residual guard.
        if post_residual > 12 && next_item_size > post_residual && nr < mean_residual * 1.5 {
            score += 3.0 * progress;
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 10.0 * progress;
    }

    // Fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Consolidation pressure.
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.45 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0 * norm_pr;
    }

    // Global slack coupling.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Pairable half-capacity residual.
    if pr == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Mild tie-break toward mean residual.
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 40.0
            + 13.0 * (fitting_bins_count.min(6) as f64)
            - 13.0 * (1.0 - progress)
            + fill * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 11.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_large {
                fresh_cost -= 12.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 16.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 13.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        // Fresh bin cheaper when best existing fit would strand a large unusable gap.
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        // Late-stream large items with poor fits.
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 40.0 * (norm_pr - 0.25) * progress;
        }
        // Early-stream fresh bins are expensive.
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 30.0 * (0.2 - progress);
        }
        // Fresh bin cheaper when item nearly fills it exactly.
        if fill > 0.9 {
            fresh_cost -= 90.0 * (fill - 0.9);
        }
        // Fresh bin cheaper when mean residual is high and fits exist.
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        // Fresh bin cheaper for large items late in the stream.
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 60.0 * (fill - 0.5) * (progress - 0.6);
        }
        // Fresh bin cheaper when no existing fit is near-tight.
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 40.0 * (norm_pr - 0.3);
        }
        // Fresh bin cheaper when next item is large and would strand residuals.
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        // Fresh bin expensive when many open bins have small residuals to compact.
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic tight-fit with progress sharpening (borrowed from best).
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 26.0;
    } else if post_residual < 7 {
        score -= 10.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        // Conserve low residuals for future small items.
        if post_residual < next_item_size {
            score += 4.0;
        }
        // Reward bins whose post_residual can host the upcoming demand.
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        // Two-item lookahead: post_residual fits next item plus tiny remainder.
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Penalize residuals in a "dead zone" — too big to waste, too small for upcoming items.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
            // Lone fit with a large residual: fresh bin keeps room for the big next item.
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        // Fresh bin cheaper when best existing fit would leave a large unusable gap.
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        // Late-stream large items: prefer fresh bin when every fit leaves >25% dead space.
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        // Early-stream fresh bins are expensive.
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        // Fresh bin cheaper when the item nearly fills it exactly.
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        // Fresh bin cheaper when few bins fit and mean residual is high.
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        // Fresh bin cheaper for large items late in the stream.
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        // Fresh bin cheaper when no existing fit is near-tight.
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        // Fresh bin cheaper when next item is large and would strand existing residuals.
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        // Fresh bin expensive when many open bins have small residuals to compact.
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

