            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        // Mid-stream awkward dead-zone fits: fresh bin cheaper.
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
