        // Existing bins near-perfect fits: keep compacting instead of expanding.
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // Fresh bin cheaper when best existing fit wastes more than mean residual.
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        // Tight-packing regime: fresh bin expensive.
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        score += fresh_cost;
    }

    score
}

