    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        // Fresh bin cheaper when existing best fit wastes more than the mean residual.
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        // MUTATION: mid-stream, when the best existing fit would leave a large
        // dead zone and the next item is big, opening a fresh bin is preferable.
        if fitting_bins_count >= 1 && progress > 0.35 && next_item_size > post_residual
            && post_residual > cap as u32 * 3 / 10 {
            fresh_cost -= 9.0 * progress;
        }
        // MUTATION: early stream — strongly discourage new bins to force
        // consolidation while the pool is still small.
        if progress < 0.15 && fitting_bins_count >= 1 {
            fresh_cost += 14.0 * (0.15 - progress) * 10.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = item_size as f64 / cap;

    // Tight-fit core: quadratic sharpening with progress.
    score += post_frac * post_frac * (30.0 + 20.0 * progress);
    score -= fill * 10.0;

    // Dead space tiers.
    if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 && bin_residual != bin_capacity {
        score -= 14.0 * (1.0 - post_residual as f64 / 4.0) * (0.5 + 0.5 * progress);
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Harmonic leftovers.
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = nr / post_residual as f64;
            if rem == 0 {
                score -= 65.0;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score -= 4.0 * (1.0 - rem as f64 / 4.0) * (0.5 + 0.5 * progress);
            } else if rem < 10 {
                score += 12.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Multi-item chain packing reward.
            if post_residual as f64 >= nr * 2.0 && post_residual as f64 - nr * 2.0 <= 4.0 {
                score -= 5.0 * (1.0 - (post_residual as f64 - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
            // Near-miss fragmentation: residual just below next item.
            if post_residual >= next_item_size.saturating_sub(6) {
                score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
            }
        }
        // Two-step lookahead: near-filling leftovers.
        if nr < post_residual as f64 && post_residual as f64 - nr <= 6.0 {
            score -= 4.5 * (1.0 - (post_residual as f64 - nr) / 6.0) * (1.0 - progress);
        }
        // Divisibility-aware reuse potential.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 10.0 * progress;
    }

    // Penalize fragmented (large-residual) bins unless fit is tight.
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - post_frac);

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Consolidation pressure when many bins are open.
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - post_frac);
    }

    // Global slack coupling.
    score += 0.03 * mean_residual * (1.0 - post_frac);

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (post_residual as f64 / mean_residual.max(1.0)) * progress;
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let next_large = next_item_size as f64 > 0.5 * cap;
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + fill * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
            // Lone fit with large residual: fresh bin keeps room for big next item.
            if next_item_size > 0 && bin_residual >= next_item_size && next_large {
                fresh_cost -= 18.0;
            }
        }
        if next_large {
            fresh_cost -= 7.0;
        }
        // Avoid compounding fragmentation: fresh bin cheaper when best fit wastes
        // more than the mean residual itself.
        if fitting_bins_count >= 1 && post_frac > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 15 && next_item_size > post_residual {
            fresh_cost -= 7.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && post_frac < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        // Late stream: fresh bins are more expensive since remaining items are few.
        fresh_cost += 8.0 * progress;
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

