        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
