            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
