    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = item_size as f64 / cap;

    // Dead space penalties
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual <= 2 {
        score -= 28.0;
    } else if post_residual < 10 {
        score += 60.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Exact-fill anticipation (strong compaction driver).
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            if rem == 0 {
                score -= 25.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 18.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < post_residual as f64 && post_residual as f64 - nr <= 6.0 {
            score -= 4.5 * (1.0 - (post_residual as f64 - nr) / 6.0) * (1.0 - progress);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && post_residual as f64 >= nr * 2.0 && post_residual as f64 - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (post_residual as f64 - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic)
    let tight = post_frac;
    score += tight * tight * (36.0 + 24.0 * progress);
    score -= fill * 10.0 * (1.0 - fill);

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
