        }
        // MUTATION: late-stream fresh-bin suppression — with few items left,
        // a new bin almost always wastes more than squeezing into any fit;
        // make the fresh bin expensive unless the item is huge.
        if remaining < 40.0 && fitting_bins_count >= 1 && fill < 0.75 {
            fresh_cost += 5.0 * (1.0 - remaining / 40.0) * (1.0 - fill);
        }
        // MUTATION: next-item sanctuary — if the next item is large and no open
        // residual could hold it after this fit, opening a fresh bin now keeps
        // a clean full bin available for it.
        if next_item_size > 0 && fitting_bins_count >= 1
            && next_item_size as f64 > mean_residual * 1.5
            && next_item_size > post_residual {
            fresh_cost -= 4.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
