    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus — post-residuals that are clean multiples of small
    // recurring item sizes can be exactly filled later.
