            fresh_cost += 8.0 * (0.12 * cap - mean_residual) / cap * 20.0 * (0.5 - progress);
        }
        // MUTATION: endgame consolidation — when few items remain, prefer to
        // squeeze into existing bins rather than spawn near-empty ones.
        if remaining < 12.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 5.0 * (1.0 - remaining / 12.0) * (1.0 - fill);
        }
        score += fresh_cost;
    }

    score
