    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus — reward post-residuals that are a clean multiple of
    // small item sizes (5/10/20/25), which recur in typical streams.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling — penalize a fit whose residual cannot hold the
    // next item but is close, weighted by how many alternatives exist.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering — protect tight fits when the stream is
    // already compacting well.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // MUTATION: residual-capture bonus — a fit whose post-residual can exactly
    // hold the *next* item AND leaves a clean remainder is doubly valuable;
    // sharpen this when the next item is large relative to the residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nr = next_item_size as f64;
        let ratio = nr / pr;
        if ratio > 0.7 {
            score -= 4.0 * (ratio - 0.7) * 10.0 * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: adaptive dead-space budget — penalize fits whose leftover
    // exceeds the running mean residual by a growing margin; the tolerance
    // shrinks as the stream progresses (early slack is fine, late slack is waste).
    if bin_residual != bin_capacity && post_residual > 0 {
        let slack = pr - mean_residual;
        if slack > 0.0 {
            let tol = 18.0 * (1.0 - progress) + 4.0;
            if slack > tol {
                score += (slack - tol) * 0.35 * (0.5 + 0.5 * progress);
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
