        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus — reward post-residuals that are clean multiples of
    // small item sizes (5/10/20/25), which recur and can be exactly filled later.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling — penalize a fit whose residual cannot hold the
    // next item but is close, weighted by how many alternatives exist.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering — protect tight fits harder when the stream is
    // already compacting well (small mean residual = precious space).
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // MUTATION: competition-aware tightness — when several bins can fit the
    // item, only the tightest one deserves priority; sharpen the contrast by
    // rewarding small post-residuals proportionally to fitting_bins_count so
    // the runner-up fits are clearly separated from the winner.
    if bin_residual != bin_capacity && post_residual > 0 && fitting_bins_count >= 2 {
        score += norm_pr * (fitting_bins_count.min(6) as f64) * 3.0 * (0.3 + 0.7 * progress);
    }

    // MUTATION: exact-chunk anticipation — if the next item divides the
    // post-residual into chunks of exactly the item size (e.g. residual 24,
    // next 8), this bin becomes a perfect future container.
    if next_item_size > 0 && post_residual > next_item_size
        && post_residual % next_item_size == 0 {
        score -= 5.0 + 3.0 * progress;
    }

    // MUTATION: dead-space floor guard — residuals just above the next item
    // size that leave a sliver are the worst kind of fragmentation; penalize
    // proportionally to how small the sliver is.
    if next_item_size > 0 && post_residual > next_item_size {
        let sliver = post_residual - next_item_size;
        if sliver <= 3 {
            score += 4.0 * (1.0 - sliver as f64 / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        // Fresh bin cheaper when existing best fit wastes more than the mean residual.
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        // Fresh bin slightly more attractive late in the stream when remaining
        // items are few (spreading waste matters less).
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        // Preserve-large-residual discount: when the fresh item is small and
        // the current best residual is large, opening a new bin preserves a
        // large reusable residual.
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        // MUTATION: stream-tail fresh-bin suppression — when many items remain,
        // a fresh bin opened now will keep absorbing small items and become a
        // long-lived low-density bin; make fresh bins costlier early/mid-stream
        // unless the item is big enough to justify the space.
        if remaining > 200.0 && fill < 0.35 && fitting_bins_count >= 1 {
            fresh_cost += 4.0 * (1.0 - fill / 0.35) * (0.5 + 0.5 * progress);
        }
        // MUTATION: endgame fresh-bin discount — with very few items left, the
        // cost of a partially-filled extra bin is bounded, so allow opening one
        // rather than forcing a bad squeeze fit.
        if remaining <= 5.0 && fitting_bins_count >= 1 && norm_pr > 0.05 {
            fresh_cost -= 6.0 * (1.0 - remaining / 5.0) * norm_pr * 10.0;
        }
        // MUTATION: divisibility-aware fresh decision — if the best existing
        // residual would be exactly consumed by the next item, never open a
        // fresh bin.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual == next_item_size {
            fresh_cost += 12.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
