    // "clean" value (multiple of 10 or 25) and the item would break it into a
    // messy fragment, mildly discourage; when the item leaves an equally clean
    // residual, reward. Clean residuals are statistically more reusable.
    if bin_residual != bin_capacity && post_residual > 0 {
        let clean_after = post_residual % 10 == 0 || post_residual % 25 == 0;
        let clean_before = bin_residual % 10 == 0 || bin_residual % 25 == 0;
        if clean_after {
            score -= 2.0 + 2.0 * (1.0 - progress);
        } else if clean_before && post_residual > 8 {
            score += 1.5 * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION: late-stream exact-chain bonus — with few items left, a fit that
    // lets the next item close the bin completely is worth more, since there
    // are fewer opportunities to repair waste.
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    if next_item_size > 0 && post_residual == next_item_size && remaining < 40.0 {
        score -= 10.0 * (1.0 - remaining / 40.0);
