    // fit the item and this one leaves a residual much larger than the smallest
    // possible alternative (approximated by mean_residual), penalize harder
    // mid-stream to push items toward tighter homes.
    if bin_residual != bin_capacity && fitting_bins_count >= 3 && post_residual > 0
