        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        // Fresh-bin discount when the next item is large enough that
        // no existing residual could hold it anyway.
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        // Discourage fresh bins when the current fit is near-exact.
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // MUTATION: fresh-bin cost scales with how many items remain — opening
        // a bin early strands a residual for a long time; late in the stream a
        // fresh bin's residual is quickly consumed. Steepen the early-stream
        // penalty proportionally to remaining stream length.
        if fitting_bins_count >= 1 && remaining > 60.0 {
            fresh_cost += 2.0 * ((remaining - 60.0) / 200.0).min(1.5);
        }
        // MUTATION: if the next item is small enough to fit into *any* plausible
        // residual (i.e. next <= mean_residual), a fresh bin is safe — its
        // leftover will be reused. Discount slightly.
        if fitting_bins_count >= 1 && next_item_size > 0
            && (next_item_size as f64) <= mean_residual.max(1.0) {
            fresh_cost -= 4.0;
        }
        score += fresh_cost;
    }

    score
}

