    // Waste-forecast coupling — penalize a fit whose residual cannot
    // hold the *next* item but is close, weighted by how many alternatives exist.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering — the lower the observed mean residual,
    // the more aggressively we should protect tight fits (small residuals are
    // precious when the stream is already compacting well).
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // MUTATION (refined): dead-space budget — penalize fits whose resulting
    // residual exceeds the running mean residual by a wide margin; such fits
    // create fragments that are statistically unlikely to be reused. Weight
    // grows with stream progress since fewer chances remain to repair waste.
    // The reward side is now scaled by how many alternative bins exist: when
    // alternatives are plentiful, keeping residuals below the mean is more
    // valuable (we can afford to be selective).
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            let alt_weight = 1.0 + 0.25 * (fitting_bins_count.min(4) as f64);
            score += 0.35 * excess * (0.3 + 0.7 * progress) * alt_weight;
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress)
                * (0.6 + 0.4 * (fitting_bins_count.min(3) as f64 / 3.0));
        }
    }

    // MUTATION: two-item lookahead synergy — if the next item fits the post
    // residual AND the item after conceptually (next+item) also fits the bin
    // residual, this bin can absorb two items: strong compaction signal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // MUTATION: fragment-shape guard — a post-residual that is "stranded"
    // (larger than the next item but smaller than next+6) creates a sliver
    // that blocks both tight fits and chain fills. Penalize proportionally
    // to remaining stream length.
    if next_item_size > 0 && post_residual > next_item_size
        && post_residual < next_item_size + 6 && progress > 0.35 {
        let sliver = (post_residual - next_item_size) as f64;
        score += 2.5 * (1.0 - sliver / 6.0) * progress;
    }

    // MUTATION: triple-fill anticipation — reward bins whose residual can
    // absorb the next item twice (or item+next+next), a strong compaction
    // signal for streams with recurring small items.
    if next_item_size > 0 && post_residual >= next_item_size * 2 {
        let rem2 = post_residual - next_item_size * 2;
        if rem2 <= 4 {
            score -= 3.0 * (1.0 - rem2 as f64 / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
