    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus — residuals divisible by 10/5 recur in typical streams.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling — near-miss vs next item weighted by alternatives.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering — protect tight fits when stream is compacting well.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // MUTATION: dead-space budget — penalize fits whose residual exceeds the
    // running mean residual by a wide margin.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // MUTATION: two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        // Fresh bin cheaper when existing best fit wastes more than the mean residual.
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        // Late stream: spreading waste matters less when few items remain.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        // Small item into a large residual: preserve the reusable residual.
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        // Fresh-bin discount when next item is large enough that no residual holds it.
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        // Discourage fresh bins when current fit is near-exact.
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // MUTATION: guard against opening fresh bins when a near-perfect fit exists
        // (waste < 5 units) — always prefer using the open bin in that case.
        if fitting_bins_count >= 1 {
            let gap = (bin_residual - item_size) as f64;
            if gap <= 5.0 {
                fresh_cost += 40.0 * (1.0 - gap / 5.0);
            }
        }
        // MUTATION: late-stream consolidation — with few remaining items, prefer
        // squeezing into open bins even with moderate waste.
        if remaining < 60.0 && fitting_bins_count >= 1 {
            fresh_cost += 0.06 * (60.0 - remaining);
        }
        // MUTATION: many alternatives with small residuals — a fresh bin is
        // wasteful; raise its cost.
        if fitting_bins_count >= 3 && mean_residual < 12.0 {
            fresh_cost += 6.0 * (fitting_bins_count.min(8) as f64 - 2.0);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // MUTATION: tri-item chain potential — reward residuals that can absorb
    // the next item plus a second copy (or a complementary small item), a
    // stronger compaction signal than the two-item synergy alone.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: residual-compatibility shaping — penalize fits that leave a
    // residual in the "awkward band" (just above typical small item sizes but
    // below the next item), which is statistically hard to reuse; the penalty
    // sharpens with progress as repair opportunities vanish.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // MUTATION: fresh-bin discount when the best alternative leaves a
        // stranded residual that the next item cannot use — opening a fresh bin
        // preserves the large residual intact for future large items.
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        // MUTATION: late-stream fresh-bin penalty — with few items remaining,
        // a new bin almost always wastes more than squeezing into an existing
        // poor fit, since there is little future left to reuse the fresh residual.
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Dead space penalties
    if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 45.0;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            if rem == 0 {
                score -= 65.0;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 10 {
                score += 12.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            // Divisibility-aware reuse: residual divisible by next item
            // supports multi-item chains.
            if post_residual % next_item_size.max(1) == 0 && rem > 0 {
                score -= 8.0 + 2.0 * progress;
            }
            // Two-copy chain potential.
            if post_residual >= next_item_size * 2 {
                let rem3 = post_residual - next_item_size * 2;
                if rem3 <= 4 {
                    score -= 4.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
                }
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
            // Stranded residual just below next item: hard to reuse later.
            let stranded = (next_item_size - post_residual) as f64;
            if stranded <= 8.0 && post_residual > 6 {
                score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic)
    let tight = post_frac;
    score += tight * tight * 36.0;
    score -= (item_size as f64 / cap) * 10.0;

    // Exact-fill anticipation (borrowed idea): residual equals item exactly.
    if bin_residual == item_size && bin_residual < bin_capacity {
        score -= 60.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 14.0 - 3.0 * (bin_residual - item_size) as f64;
    }

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - tight);

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - tight);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Dead-space budget: push post_residual toward the mean residual shape.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = post_residual as f64 - mean_residual;
        if excess > 0.0 {
            score += 0.30 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            // Lone fit with a large residual: fresh bin keeps room for the
            // big next item instead of fragmenting the only usable bin.
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 7.0;
        }
        // Late stream: fresh bins are more expensive since remaining items are few.
        fresh_cost += 8.0 * progress;
        // Late-stream extra penalty: little future left to reuse a fresh residual.
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        // Fresh-bin discount when the best alternative leaves a stranded
        // residual the next item cannot use — preserve the residual intact.
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        // Near-perfect alternative exists: fresh bin very costly.
        if fitting_bins_count >= 1 && post_frac <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // Fragmented alternatives with big residuals: fresh bin competes well.
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count >= 1 && post_frac > 0.15 && (item_size as f64 / cap) < 0.4 {
            fresh_cost -= 6.0 * (post_frac - 0.15) * 10.0 * (1.0 - (item_size as f64 / cap) * 2.0);
        }
        // Large item late in the stream: squeezing is fine, fresh is wasteful.
        if (item_size as f64 / cap) > 0.9 {
            fresh_cost -= 9.0 * ((item_size as f64 / cap) - 0.9) * 10.0;
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Residual-compatibility shaping.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // MUTATION: dead-space budget reinforcement — sharpen the excess penalty
    // late in the stream so residual accumulation is punished harder exactly
    // when repair opportunities vanish; also credit below-mean residuals
    // proportionally to progress for stronger compaction steering.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += (0.35 + 0.45 * progress) * excess;
        } else {
            score -= (0.15 + 0.25 * progress) * (-excess);
        }
    }

    // MUTATION: post-residual granularity shaping — reward residuals that sit
    // within the small-item absorbable band (<= 10) with a smooth quadratic
    // curve instead of only the tiered cutoffs, tightening mid-band fits.
    if bin_residual != bin_capacity && post_residual > 0 && post_residual <= 10 {
        score -= 2.0 * (1.0 - pr / 10.0) * (1.0 - pr / 10.0) * (0.6 + 0.8 * progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // Fresh-bin discount when the best alternative leaves a stranded residual.
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        // Late-stream fresh-bin penalty.
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        // MUTATION: endgame fresh-bin hard block — when almost nothing remains,
        // opening a fresh bin is essentially pure waste; escalate the penalty
        // quadratically so the last few items always compact into open bins.
        if remaining < 5.0 && fitting_bins_count >= 1 {
            fresh_cost += 14.0 * (1.0 - remaining / 5.0) * (1.0 - remaining / 5.0);
        }
        score += fresh_cost;
    }

    score
}

