    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Residual-compatibility shaping — penalize stranded residuals.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // MUTATION: projected-waste steering — compare the waste this placement
    // creates (post_residual) against the waste of the alternative best fit
    // implied by the mean residual; sharpen the pressure as the stream runs
    // out so late placements squeeze harder into tight bins.
    if bin_residual != bin_capacity && post_residual > 0 && total_items > step_index + 1 {
        let remaining = (total_items - step_index - 1) as f64;
        let urgency = 1.0 / (1.0 + remaining / 50.0);
        let waste_gap = pr - mean_residual.max(1.0);
        if waste_gap > 0.0 {
            score += 0.9 * waste_gap * urgency;
        } else {
            score -= 0.5 * (-waste_gap) * urgency;
        }
    }

    // MUTATION: capacity-aware residual tiling — if the post-residual can
    // tile the remaining bin space with the next item's size almost exactly,
    // this bin is a natural "chain home"; reward it proportionally to how
    // close the tiling lands to a perfect fill.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        let tile_waste = post_residual - k * next_item_size;
        if k >= 2 && tile_waste <= 3 {
            score -= 2.0 + 2.5 * (1.0 - tile_waste as f64 / 3.0) * (0.3 + 0.7 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // Fresh-bin discount when the best alternative leaves a stranded residual.
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        // Late-stream fresh-bin penalty.
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        // MUTATION: fresh-bin rejection when some open bin can chain-fit the
        // next item exactly — a new bin would split what could be a perfect
        // tandem, so make the fresh option clearly unattractive there.
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual == next_item_size {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // MUTATION: mid-stream large-item fresh-bin discount — when the item
        // is big and many bins compete, a fresh bin absorbs it cleanly instead
        // of fragmenting an existing bin's reusable residual.
        if fitting_bins_count >= 3 && fill > 0.55 && progress > 0.35 {
            fresh_cost -= 4.0 * (fill - 0.55) * 10.0 * progress;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
