    // MUTATION: adaptive tight-fit band — instead of a fixed post_residual <= 2
    // tier, scale the reward by how rare small residuals currently are: when
    // mean_residual is small, tiny leftovers are precious and get extra credit.
    if post_residual > 0 && post_residual <= 5 && bin_residual != bin_capacity {
        let scarcity = (mean_residual / 12.0).clamp(0.0, 1.0);
