    // MUTATION: dead-space ratio shaping — penalize the fraction of the bin
    // that will remain unusable by the next item, sharpened by progress, so
    // residual space is spent only when it yields near-perfect chains.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let unusable = if next_item_size as f64 > pr {
            pr
        } else {
            (pr - (pr as u32 / next_item_size.max(1) * next_item_size.max(1)) as f64)
