        if dead_ratio > 0.02 {
            score += dead_ratio * (14.0 + 22.0 * progress);
        }
    }

    // MUTATION: exact residual-match bonus against the running mean residual —
    // leaving a post-residual equal to the mean residual keeps future small
    // items perfectly reusable across bins.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mdiff = (pr - mean_residual).abs();
        if mdiff <= 2.0 {
            score -= 3.0 * (1.0 - mdiff / 2.0) * (0.4 + 0.6 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
