    // MUTATION (refined): dead-space entropy guard — residuals that neither
    // the next item nor the mean residual can absorb are near-permanent
    // waste. Sharpen into a quadratic term whose strength grows with both
    // progress and the fraction of the bin the dead space represents.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
