    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
    }

    // Reward bins whose post_residual equals a common size bucket.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: dead-space entropy guard — residuals neither the next item
    // nor the mean residual can absorb are near-permanent waste.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            score += 0.10 * (unusable - mean_residual) * (0.5 + progress);
        }
    }

    // MUTATION: zero-waste chain reward — post-residual that is a multiple
    // of the next item's size is the strongest compaction signal.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    // MUTATION: small-item sink bonus — residuals in 3..=10 the next item
    // can't use but which commonly host future small items.
    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    // MUTATION: dead-space budget — penalize excess over mean residual,
    // reward below-mean residuals.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // MUTATION: two-item synergy — bin can host item plus next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // MUTATION: tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
