        // implicitly discards the mean residual of open bins.
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        // MUTATION: fresh-bin discount when next item is huge and no open
        // residual could host it — avoids double-stranding.
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        // MUTATION: fresh bin cheaper when best existing fit leaves a gap
        // larger than the typical item size (unreclaimable waste).
        if fitting_bins_count >= 1 {
            let gap = (bin_residual - item_size) as f64;
            let _ = gap; // post_residual already encodes the gap for the best fit
            if norm_pr > mean_residual / cap * 1.2 {
                fresh_cost -= 5.0;
            }
        }
        // MUTATION: end-of-stream guard — late in the stream, prefer compacting
        // into existing bins rather than opening fresh ones.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        score += fresh_cost;
    }

    score
}

