        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Triple-fit compaction.
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
