    }

    // MUTATION: perfect-fill chain anticipation — if the current item leaves
    // a residual exactly equal to the next item AND the bin after that would
    // be empty, this is a two-item exact closure; reward strongly since it
    // removes all dead space from this bin's future.
    if next_item_size > 0 && post_residual == next_item_size
        && bin_residual == item_size + next_item_size {
        score -= 10.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: residual-vs-mean absorption test — when the leftover residual
    // is smaller than the observed mean residual, future small items are
    // statistically likely to absorb it; discount the leftover accordingly.
    if bin_residual != bin_capacity && post_residual > 0 && pr <= mean_residual {
        score -= 1.2 * (1.0 - pr / mean_residual.max(1.0)) * (0.4 + 0.6 * progress);
