        // residual; taper the discount by remaining count.
        if remaining < 8.0 && fitting_bins_count >= 1 && fill > 0.5 {
            fresh_cost -= 6.0 * (1.0 - remaining / 8.0) * fill;
        }
        // MUTATION: early-stream consolidation brake — opening bins early
        // multiplies later fragmentation; make fresh bins pricier while the
        // stream is young and mean residual is still healthy.
        if progress < 0.35 && mean_residual > 12.0 && fitting_bins_count >= 2 {
            fresh_cost += 3.0 * (0.35 - progress) * (mean_residual / cap) * 20.0;
        }
        score += fresh_cost;
    }

    score
}

