    // Stranded-residual forecast.
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Triple-fit compaction.
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space entropy guard — residuals that neither the next item nor
    // the mean residual can absorb are near-permanent waste; sharpened
    // quadratically with progress to punish late-stream stranding harder.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // Zero-waste chain reward — leaving exactly a multiple of the next
    // item's size as post-residual is the strongest compaction signal.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    // Small-item sink bonus — residuals in 3..=10 the next item can't use
    // but which commonly host future small items; tapered by progress.
    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    // MUTATION: exact-decomposition reward — when the post-residual can be
    // tiled by the next item with zero waste AND the current item also
    // divided the residual evenly, this bin is a perfect chain; deepen the
    // discount to lock in these configurations over loose fits.
    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: near-mean absorbability credit — if the leftover post-residual
    // is close to the mean residual, future items statistically fit it; reward
    // this alignment, strongest mid-stream where compaction compounds.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        // Fresh-bin dead-space accounting — charge the fresh bin for the
        // latent mean residual waste of open bins, mid/late stream.
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        // Fresh-bin discount when next item is huge and no open residual
        // could host it — avoids double-stranding.
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        // MUTATION: fresh-bin surcharge when a fitting bin leaves a
        // perfectly absorbable residual (≤ 2 or divisible by next item) —
        // opening a new bin would destroy a near-zero-waste chain.
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION: fresh-bin discount when the best fitting bin would strand
        // a residual larger than the next item and the mean residual — i.e.
        // unusable dead space — scaled by how much larger it is.
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // MUTATION: multi-item chain packing reward (borrowed from best).
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-item lookahead synergy.
        if nr > 0.0 && post_residual >= next_item_size {
            let pair = item_size + next_item_size;
            if bin_residual >= pair {
                score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
            }
        }
        // Harmonic reuse — residual that fits the next item k times exactly.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // MUTATION: near-mean absorbability credit — leftover close to mean
    // residual is statistically reusable; reward strongest mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: mid-stream tight-fit bonus (borrowed from best).
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // MUTATION: dead-space entropy guard — residuals the next item can't
    // use and above mean residual are near-permanent waste; sharpened
    // quadratically with progress.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual;
        if e > 0.0 {
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // MUTATION: near-miss fragmentation penalty (borrowed from best).
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // MUTATION: waste-threshold trigger — fragmentation risk nudges toward
    // a fresh bin instead of a loose fit.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Stranding residuals no plausible future item can use (mean residual proxy).
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
    }

    // Reward common-bucket residuals (5/10/25) for divisibility compaction.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        // Mid-stream awkward dead zone discount.
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        // Expensive when existing bins are near-perfect fits.
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // MUTATION (borrowed from best): near-tight fits block fresh bins.
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        // MUTATION: fresh-bin surcharge when a fitting bin leaves a
        // perfectly absorbable residual (≤2 or divisible by next item).
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION: fresh-bin discount when the best fit would strand a
        // residual larger than both next item and mean residual.
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        // MUTATION: remaining-stream aware fresh-bin pricing (borrowed).
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        // Fresh-bin dead-space accounting — charge for latent mean residual
        // waste of open bins, mid/late stream.
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        // Discount when next item is huge and no open residual could host it.
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Residual-compatibility shaping.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // Mid-band residual deadness.
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Dual-harmonic reuse.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    // Stranded-residual forecast.
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Triple-fit compaction.
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space entropy guard — sharpened with a cubic late-stream term so
    // stranding is punished harder exactly where it hurts most.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
            score += 0.004 * e * e * (progress * progress);
        }
    }

    // Zero-waste chain reward.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    // Small-item sink bonus.
    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    // MUTATION: exact-decomposition reward.
    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: near-mean absorbability credit.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: perfect-tile chain bonus — post-residual that can host the
    // next item AND still leave an exact multiple of it afterwards locks
    // the bin into a zero-waste chain; discount scales with chain depth k.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 && post_residual % next_item_size == 0 {
            score -= 3.0 * (k.min(5) as f64) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION: stranded-gap shaping — penalize residuals that fall just
    // below the next item by an amount proportional to the miss, so bins
    // with "almost usable" leftovers are deprioritized against bins whose
    // leftover is fully usable, sharpening the fit boundary late-stream.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0
        && next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 12.0 {
            score += 0.25 * miss * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        // Fresh-bin dead-space accounting.
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        // Fresh-bin discount for huge next item.
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        // MUTATION: fresh-bin surcharge when a fitting bin leaves a
        // perfectly absorbable residual.
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION: fresh-bin discount when the best fitting bin would strand
        // unusable dead space.
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        // MUTATION: fresh-bin discount when the item exactly fills the fresh
        // bin (zero post-residual) AND the next item is large enough that no
        // open residual could host it — this is the highest-value fresh-bin
        // scenario and previously was under-weighted.
        if fitting_bins_count >= 1 && post_residual == 0 && next_item_size > 0
            && next_item_size as f64 > mean_residual * 1.5 {
            fresh_cost -= 10.0 * (0.4 + 0.6 * progress);
        }
        // MUTATION: fresh-bin surcharge scaled by how many fitting bins leave
        // a residual the next item can chain into — protects multi-way chains
        // that the flat surcharge above only partially covers.
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0
            && post_residual >= next_item_size {
            fresh_cost += 3.0 * (0.5 + 0.5 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Two-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Harmonic reuse — residual fits next item k times exactly.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
            if k >= 2 {
                score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
    }

    // Common-size bucket reward.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: near-mean absorbability credit — leftover close to mean residual
    // statistically hosts future items; strongest mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: dead-space entropy guard — residuals neither the next item nor
    // the mean residual can absorb are near-permanent waste.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // MUTATION: near-miss fragmentation penalty — residual just under next item.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // MUTATION: waste-threshold trigger — large gap relative to mean residual
    // nudges toward fragmentation risk.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // MUTATION: fresh-bin surcharge when a fitting bin leaves a perfectly
        // absorbable residual — don't destroy a near-zero-waste chain.
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION: fresh-bin discount when the best fit would strand a residual
        // larger than the mean residual — unusable dead space.
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        // MUTATION: fresh-bin surcharge when open bins are near-perfect fits —
        // keep compacting instead of expanding.
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // MUTATION: end-of-stream — cheap fresh bins for exact final fits,
        // expensive otherwise.
        if remaining < 20.0 && fitting_bins_count >= 1 {
            if fill > 0.85 {
                fresh_cost -= 5.0 * (1.0 - remaining / 20.0);
            } else {
                fresh_cost += 4.0 * (1.0 - remaining / 20.0) * (1.0 - fill);
            }
        }
        // MUTATION: fresh-bin dead-space accounting — charge for latent mean
        // residual waste of open bins, mid/late stream.
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        // MUTATION: fresh-bin discount when next item is huge and no open
        // residual could host it.
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        // MUTATION: fresh-bin discount when best fit leaves residual in the
        // awkward 8..20 dead zone mid-stream.
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 && next_item_size > post_residual {
            fresh_cost -= 4.0 * progress;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Residual-compatibility shaping.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // Mid-band residual deadness.
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Dual-harmonic reuse.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    // Stranded-residual forecast.
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Triple-fit compaction.
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space entropy guard — residuals that neither the next item nor
    // the mean residual can absorb are near-permanent waste; sharpened
    // quadratically with progress to punish late-stream stranding harder.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // Zero-waste chain reward — leaving exactly a multiple of the next
    // item's size as post-residual is the strongest compaction signal.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    // Small-item sink bonus — residuals in 3..=10 the next item can't use
    // but which commonly host future small items; tapered by progress.
    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    // Exact-decomposition reward — when the post-residual can be
    // tiled by the next item with zero waste AND the current item also
    // divided the residual evenly, this bin is a perfect chain; deepen the
    // discount to lock in these configurations over loose fits.
    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    // Near-mean absorbability credit — if the leftover post-residual
    // is close to the mean residual, future items statistically fit it; reward
    // this alignment, strongest mid-stream where compaction compounds.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: stranded-forecast dead-space sharpening — when the next item
    // cannot fit the post-residual and the leftover exceeds the mean residual
    // by a wide margin, that space is effectively permanent waste. Punish it
    // with a quadratic term that grows with stream position, complementing the
    // linear entropy guard above.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 2.0 {
            score += 0.05 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // MUTATION: absorbable-residual lock-in — when a fitting bin would leave a
    // residual the next item fits exactly or with ≤2 waste, deepen the discount
    // late-stream so these near-perfect chains are never passed over.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 2 {
            score -= 6.0 * (1.0 - slack as f64 / 3.0) * (0.3 + 0.7 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        // Fresh-bin dead-space accounting — charge the fresh bin for the
        // latent mean residual waste of open bins, mid/late stream.
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        // Fresh-bin discount when next item is huge and no open residual
        // could host it — avoids double-stranding.
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        // Fresh-bin surcharge when a fitting bin leaves a
        // perfectly absorbable residual (≤ 2 or divisible by next item) —
        // opening a new bin would destroy a near-zero-waste chain.
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin discount when the best fitting bin would strand
        // a residual larger than the next item and the mean residual — i.e.
        // unusable dead space — scaled by how much larger it is.
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        // MUTATION: fresh-bin surcharge when the current item nearly fills an
        // open bin (post_residual ≤ 4) — a fresh bin here wastes the almost
        // complete open bin's remaining budget, which late-stream compounds.
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        // MUTATION: fresh-bin discount when the best fitting bin strands a
        // residual in the "dead band" (next item misses by ≤ 4 and leftover
        // exceeds mean residual) — that space is statistically permanent.
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Residual-compatibility shaping.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // Mid-band residual deadness.
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Dual-harmonic reuse.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    // Stranded-residual forecast.
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Triple-fit compaction.
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space entropy guard.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // Zero-waste chain reward.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    // Small-item sink bonus.
    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    // Exact-decomposition reward.
    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    // Near-mean absorbability credit.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: stranded-forecast dead-space sharpening (retained & slightly
    // amplified late-stream where dead space compounds bin count).
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 2.0 {
            score += 0.05 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // MUTATION: absorbable-residual lock-in (retained).
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 2 {
            score -= 6.0 * (1.0 - slack as f64 / 3.0) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (new): residual-variance-aware tightness bonus — when the
    // stream's residuals are tightly clustered (low variance proxy via mean
    // residual being small), favoring the bin whose post-residual sits
    // closest to that mean maximizes the chance of future absorption.
    if bin_residual != bin_capacity && post_residual > 0 && mean_residual < 12.0 {
        let d = (pr - mean_residual).abs();
        score -= 1.2 * (1.0 - d / 12.0) * (1.0 - norm_pr) * progress;
    }

    // MUTATION (new): late-stream exact-zero chase — with few items left,
    // zero post-residual is the dominant compaction signal; deepen the
    // discount quadratically as the stream nears its end.
    if post_residual == 0 && bin_residual != bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 40.0 {
            score -= 3.0 * (1.0 - remaining / 40.0) * (1.0 + progress);
        }
    }

    // MUTATION (new): oversized-item reservation — when the next item is
    // large (> 0.4 capacity) and this bin would leave a residual smaller
    // than it, that residual is almost surely dead; penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual
        && (next_item_size as f64) > 0.4 * cap {
        score += 2.5 * (1.0 - post_residual as f64 / next_item_size as f64) * (0.3 + 0.7 * progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        // Fresh-bin surcharge for near-complete open bins (retained).
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        // Fresh-bin discount for dead-band stranding (retained).
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        // MUTATION (new): fresh-bin surcharge when an open bin can tile the
        // next item exactly (post_residual == next_item_size) — opening a
        // fresh bin there forfeits a guaranteed zero-waste placement.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual == next_item_size {
            fresh_cost += 9.0 * (0.5 + 0.5 * progress);
        }
        // MUTATION (new): fresh-bin discount when the only fitting bins would
        // strand residuals far above the next item AND the item is small —
        // the item is cheap to place anywhere, so consolidate elsewhere.
        if fitting_bins_count >= 1 && fill < 0.25 && post_residual > 0
            && next_item_size > post_residual && post_residual as f64 > mean_residual * 1.6 {
            fresh_cost -= 4.0 * (1.0 - fill * 4.0) * (0.5 + 0.5 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
