        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
    }

    // Reward bins whose post_residual equals a common size bucket.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION (from best): near-miss fragmentation penalty — residual just
    // below the next item's size is stranded space; punish its proximity.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // MUTATION (from best): dead-space entropy guard — quadratic punishment
    // for residuals neither the next item nor mean residual can absorb,
    // sharpened with progress to punish late-stream stranding harder.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // MUTATION (from best): absorbable-residual lock-in — deepen the discount
    // for near-perfect chains with slack ≤ 3.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (from best): near-mean absorbability credit — leftover close
    // to the mean residual statistically hosts future items.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (from best): waste-threshold trigger — fragmentation risk
    // nudges toward a fresh bin when gap exceeds typical item scale.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        // Fresh bin cheaper mid-stream when all fits leave awkward 8..20 gaps.
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        // Fresh bin expensive when existing bins are near-perfect fits.
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // MUTATION (from best): fresh-bin surcharge when the best fitting bin
        // leaves a residual the next item can chain into with zero waste.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (from best): fresh-bin surcharge when the current item
        // nearly fills an open bin — a fresh bin wastes almost-complete budget.
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        // MUTATION (from best): fresh-bin discount when the best fitting bin
        // strands a residual in the frozen band (next item misses by ≤ 4).
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        // MUTATION (from best): fresh-bin surcharge when a fitting bin leaves
        // a perfectly absorbable residual (≤ 2 or divisible by next item).
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (from best): fresh-bin surcharge when many bins fit but all
        // leave tight residuals — natural fit; avoid fragmenting late-stream.
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Residual-compatibility shaping.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // Mid-band residual deadness.
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Dual-harmonic reuse.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    // Stranded-residual forecast.
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Triple-fit compaction.
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space entropy guard.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // Zero-waste chain reward.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    // Small-item sink bonus.
    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    // Exact-decomposition reward.
    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    // Near-mean absorbability credit.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (retained): stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // MUTATION (retained): absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (retained): dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // MUTATION (new): cumulative-waste budget — the aggregate stranded
    // capacity across open bins (approximated by mean_residual * open count)
    // is the true cost driver; bins that would add more than the running
    // average waste are charged progressively harder late-stream, while
    // bins that finish below the running average are credited. This directly
    // targets the diagnosed dead-space ratio weakness.
    if bin_residual != bin_capacity && post_residual > 0 {
        let avg_waste = mean_residual * (open_bins_count.max(1) as f64);
        let marginal = pr - mean_residual;
        if marginal > 0.0 {
            score += marginal * (0.10 + 0.25 * progress)
                * (1.0 + (avg_waste / cap).min(1.0));
        } else {
            score -= (-marginal) * (0.08 + 0.20 * (1.0 - progress));
        }
    }

    // MUTATION (new): terminal compaction sprint — in the final quarter of
    // the stream, only near-perfect fits matter; residuals above a shrinking
    // budget are penalized steeply so late items don't strand space.
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    if progress > 0.75 && bin_residual != bin_capacity && post_residual > 0 {
        let budget = 8.0 * (1.0 - progress) * 4.0; // 8.0 → 0.0
        if pr > budget {
            score += (pr - budget) * (0.5 + 1.5 * (progress - 0.75) * 4.0);
        } else {
            score -= 2.0 * (1.0 - pr / budget.max(1.0));
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // MUTATION (new): fresh-bin terminal lockout — in the final stretch,
        // opening a bin is almost always worse than any fit; surcharge grows
        // as remaining items shrink, unless no open bin can host the item.
        if fitting_bins_count >= 1 && remaining < 25.0 {
            fresh_cost += 6.0 * (1.0 - remaining / 25.0) * (0.5 + 0.5 * progress);
        }
        // MUTATION (new): fresh-bin absorbability probe — if the mean
        // residual suggests open bins can still absorb several future items,
        // a fresh bin dilutes that absorbability; charge proportional to
        // remaining stream length.
        if fitting_bins_count >= 1 && mean_residual > 6.0 {
            fresh_cost += 0.20 * (mean_residual - 6.0)
                * ((remaining / (total_items.max(1) as f64)).min(1.0));
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Multi-item chain packing reward.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Prefer small post_residual relative to mean residual.
    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    // Mid-stream tight-fit bonus.
    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    // Near-miss fragmentation penalty.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // Waste-threshold trigger — fragmentation risk nudges toward a fresh bin.
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Reward bins whose post-residual exactly matches a common future chain.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    // Harmonic-fit bonus.
    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Waste-forecast coupling.
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Cumulative-waste steering.
    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    // Dead-space budget.
    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    // Two-item lookahead synergy.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Tri-item chain potential.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Residual-compatibility shaping.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    // Mid-band residual deadness.
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Dual-harmonic reuse.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    // Stranded-residual forecast.
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Triple-fit compaction.
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space entropy guard.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    // Zero-waste chain reward.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    // Small-item sink bonus.
    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    // Exact-decomposition reward.
    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    // Near-mean absorbability credit.
    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (refined): stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // MUTATION (refined): absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION: dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // MUTATION (new): late-stream exact-fit escalation — when few items
    // remain, the marginal cost of a wasted residual rises; deepen the
    // exact-fill and near-fill discounts quadratically with remaining
    // scarcity so the tail packs maximally tight.
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    if remaining < 60.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 60.0;
        if post_residual == 0 {
            score -= 12.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.0 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 4 {
                score -= 2.5 * (1.0 - rem as f64 / 5.0) * scarcity;
            }
        }
    }

    // MUTATION (new): open-bin count-aware consolidation — when many bins
    // are already open, mildly favor whichever bin absorbs the item to
    // avoid spawning parallel half-empty bins; scaled by norm_pr.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // MUTATION (new): fresh-bin surcharge tied to remaining scarcity —
        // late-stream, opening a bin wastes capacity that can never be
        // repaid; raise the cost quadratically as the stream ends unless
        // the item is huge and no open bin can host it.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // MUTATION (new): fresh-bin surcharge when an open bin would be
        // left nearly full but abandoned (post_residual <= 2) — that
        // near-complete bin's leftover is pure loss if we skip it.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation (refined: window widened, chain-aware).
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // MUTATION (new): residual-entropy compaction — bins whose leftover is
    // an awkward mid-band size (too big for typical small items, too small
    // for typical large ones) are penalized more strongly as mean residual
    // shrinks, steering picks toward bins whose leftover stays usable.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            score += (1.5 + 3.0 * tightness) * (0.35 + 0.65 * progress);
        }
    }

    // MUTATION (new): fill-depth momentum — prefer absorbing items into the
    // deepest bins so that a few bins approach completion instead of many
    // bins being uniformly half-full; quadratic in fill depth.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
    }

    // MUTATION (new): next-item sink reservation — if the next item can only
    // fit in this bin's post-residual among few candidates, lock this bin
    // for it by discounting heavily; avoids stranding the next item.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 4 && fitting_bins_count >= 1 {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // MUTATION (new): mean-residual-aware fresh-bin gate — when the
        // average leftover across open bins is already small, the stream is
        // packing tightly and a new bin would introduce fresh fragmentation;
        // when the average leftover is large, a fresh bin can consolidate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (borrowed from best).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual < bin_capacity && bin_residual - item_size <= 3 {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if nr == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = nr / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && nr > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        } else {
            score += 4.0;
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Gap-aware preference for near-fitting bins.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Fill-depth momentum: prefer absorbing into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 4 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_large {
                fresh_cost -= 14.0;
            }
        }
        if fill > 0.6 {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // MUTATION: pair-fit gate — if some open bin could host the item AND
        // the next item afterwards (post_residual covers both), opening a
        // fresh bin wastes that chain opportunity; penalize harder.
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // MUTATION: small-item consolidation — tiny items into fresh bins are
        // almost always wasteful; escalate the surcharge as fill shrinks.
        if fitting_bins_count >= 1 && fill < 0.25 {
            fresh_cost += 8.0 * (0.25 - fill) * 10.0 * (0.3 + 0.7 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (sharper near-perfect tiers).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 28.0;
    } else if post_residual < 6 {
        score -= 12.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Conserve low residuals for future small items.
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Harmonic reuse — residual that fits the next item k times exactly.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
    }

    // Reward bins whose post_residual equals a common size bucket.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: fill-depth momentum — prefer absorbing items into the deepest
    // bins so a few bins approach completion instead of many half-full bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
    }

    // MUTATION: residual-entropy compaction — penalize awkward mid-band leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            score += (1.5 + 3.0 * tightness) * (0.35 + 0.65 * progress);
        }
    }

    // MUTATION: next-item sink reservation — lock this bin for the next item.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 4 && fitting_bins_count >= 1 {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // MUTATION: scarcity surcharge — late-stream fresh bins are expensive
        // unless the item is a rescue-sized fill or very large.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // MUTATION: mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // MUTATION: fresh bin cheaper when the best existing fit leaves a gap
        // larger than typical future item needs.
        if fitting_bins_count >= 1 && bin_residual != bin_capacity {
            let gap = (bin_residual - item_size) as f64;
            if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
                fresh_cost -= 3.0 * (1.0 - progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation (refined: window widened, chain-aware).
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // MUTATION: residual-entropy compaction — bins whose leftover is
    // an awkward mid-band size (too big for typical small items, too small
    // for typical large ones) are penalized more strongly as mean residual
    // shrinks, steering picks toward bins whose leftover stays usable.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            score += (1.5 + 3.0 * tightness) * (0.35 + 0.65 * progress);
        }
    }

    // MUTATION: fill-depth momentum — prefer absorbing items into the
    // deepest bins so that a few bins approach completion instead of many
    // bins being uniformly half-full; quadratic in fill depth.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
    }

    // MUTATION: next-item sink reservation — if the next item can only
    // fit in this bin's post-residual among few candidates, lock this bin
    // for it by discounting heavily; avoids stranding the next item.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 4 && fitting_bins_count >= 1 {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
    }

    // MUTATION (new): two-step chain exhaustion — when the next item fits
    // the post-residual AND the item after it would then fit the resulting
    // residual (approximated by mean residual), this bin supports a chain
    // of fills; reward it proportionally to how tight the chain is.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if (rem2 as f64) >= mean_residual * 0.8 && rem2 <= 16 {
            let chain_quality = 1.0 - rem2 as f64 / 16.0;
            score -= 4.5 * chain_quality * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (new): residual-band matching — if post_residual falls in the
    // same size band as the mean residual (i.e. this bin's leftover will
    // blend into the population of usable leftovers), mildly reward it;
    // leftovers far from the mean create heterogeneous waste that is hard
    // to fill later.
    if bin_residual != bin_capacity && post_residual > 0 {
        let band_diff = (pr - mean_residual).abs();
        if band_diff > 10.0 && pr > mean_residual {
            score += 0.12 * (band_diff - 10.0) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (new): near-capacity lockout — bins whose post-residual would
    // be tiny (1-3) but nonzero are nearly closed; slightly prefer closing
    // them exactly via larger items, and penalize leaving them stranded
    // when the next item cannot use the sliver.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 3
        && next_item_size > post_residual {
        score += 3.0 * (4.0 - post_residual as f64) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // MUTATION: mean-residual-aware fresh-bin gate — when the
        // average leftover across open bins is already small, the stream is
        // packing tightly and a new bin would introduce fresh fragmentation;
        // when the average leftover is large, a fresh bin can consolidate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // MUTATION (new): mid-band fresh-bin gate — a new bin is especially
        // wasteful when the current item is small relative to capacity and
        // open bins still hold mid-sized leftovers; surcharge scales with
        // how much usable leftover space exists on average.
        if fitting_bins_count >= 1 && fill < 0.45 {
            let usable = mean_residual.max(0.0) / cap;
            if usable > 0.10 && usable < 0.35 {
                fresh_cost += 5.0 * (0.35 - usable) * (0.5 + 0.5 * progress) * (0.45 - fill) * 4.0;
            }
        }
        // MUTATION (new): large-item fresh-bin relief refinement — when the
        // item is very large and next item is also large, opening fresh is
        // often the only way to avoid splitting pairs; deepen the relief.
        if fitting_bins_count >= 1 && fill > 0.75 && next_item_size as f64 > 0.6 * cap {
            fresh_cost -= 7.0 * (fill - 0.75) * 4.0 * (0.5 + 0.5 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 28.0;
    } else if post_residual < 7 {
        score -= 10.0 - 0.5 * (6 - post_residual) as f64;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-zone penalty.
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residual penalty via mean residual proxy.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
    }

    // Common-size bucket reward.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: fill-depth momentum — prefer absorbing into the deepest bins
    // so bins approach completion rather than staying uniformly half-full.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
    }

    // MUTATION: residual-entropy mid-band penalty — leftovers in the awkward
    // band that the next item just barely misses are penalized.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as u32) > post_residual
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            score += (1.5 + 3.0 * tightness) * (0.35 + 0.65 * progress);
        }
    }

    // MUTATION: next-item sink reservation — lock bins whose post-residual
    // barely hosts the next item, avoiding stranding.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 4 && fitting_bins_count >= 1 {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
    }

    // MUTATION: late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // MUTATION: mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // MUTATION: fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // MUTATION: fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        score += fresh_cost;
    }

    score
}

