    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation (refined: window widened, chain-aware).
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Residual-entropy compaction: penalize awkward mid-band leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            score += (1.5 + 3.0 * tightness) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 4 && fitting_bins_count >= 1 {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0);
    }

    // MUTATION (gen 33): multi-step divisibility chain bonus — a leftover that
    // can be tiled exactly by the next item two or three times over is a
    // compaction magnet; deepen the discount as the chain lengthens, weighted
    // by how little stream remains (chains matter most when items still flow).
    if next_item_size > 0 && post_residual >= next_item_size * 2 && next_item_size > 0 {
        let k = (post_residual / next_item_size).min(4) as f64;
        let stream_pressure = (remaining / (total_items.max(1) as f64)).max(0.2);
        score -= 1.8 * (k - 1.0) * stream_pressure * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 33): orphan-residual quarantine — if the leftover after
    // placement cannot host the next item AND exceeds the mean residual by a
    // wide margin, this bin is creating an orphan pocket; escalate the penalty
    // quadratically with the orphan size but only once the stream is deep
    // enough that orphans rarely get rescued.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let orphan = pr - next_item_size as f64;
        if orphan > 0.0 && pr > mean_residual.max(1.0) * 1.3 {
            let sev = orphan / cap;
            score += 22.0 * sev * sev * progress + 1.2 * orphan / cap;
        }
    }

    // MUTATION (gen 33): near-closure magnetism — bins one small item away
    // from full closure deserve priority over mid-fit bins; sharpen the pull
    // when the closing item is likely to arrive soon (small items dominate
    // late in tight streams).
    if bin_residual != bin_capacity && bin_residual <= 12 {
        let pull = 1.0 - bin_residual as f64 / 13.0;
        let small_next = next_item_size > 0 && (next_item_size as f64) <= bin_residual as f64;
        score -= (4.0 + 3.0 * pull) * pull * if small_next { 1.6 } else { 0.7 }
            * (0.3 + 0.7 * progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // MUTATION (gen 33): orphan-creation guard for fresh bins — opening a
        // new bin while some open bin would strand a large orphan is fine, but
        // opening one when the best existing fit leaves only a tiny sliver is
        // pure fragmentation; charge a sliver tax scaled to how tight the
        // existing alternatives already are.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            let sliver = 1.0 - post_residual as f64 / 9.0;
            fresh_cost += 9.0 * sliver * sliver * (0.5 + 0.5 * progress);
        }
        // MUTATION (gen 33): item-size vs mean-residual harmony — if the
        // current item is smaller than the mean leftover, existing bins are
        // the natural habitat; a fresh bin here breaks the tight packing
        // pattern and should cost more as mean residual shrinks.
        if fitting_bins_count >= 1 && (item_size as f64) < mean_residual {
            let harmony = 1.0 - item_size as f64 / mean_residual.max(1.0);
            fresh_cost += 7.0 * harmony * (0.4 + 0.6 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation (refined: window widened, chain-aware).
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Residual-entropy compaction — awkward mid-band leftovers penalized
    // more strongly as mean residual shrinks (refined: weight scales with
    // how far above the mean the leftover sits, catching drift early).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins
    // (refined: cubic term rewards near-complete bins harder late-stream).
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation — lock bins whose post-residual will
    // tightly hold the next item (refined: window widened to 6, scaled
    // by scarcity of fitting bins).
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // MUTATION (new): dead-space liquidity gate — a bin whose post-residual
    // is smaller than the running mean residual is effectively "sealed"
    // space; reward sealing it now (its leftover will never be used), but
    // penalize leaving a leftover that is barely below the mean (it looks
    // usable but likely isn't, wasting capacity silently).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual > 0 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // MUTATION (new): item-size vs. mean-residual fresh gate — when the
        // current item is small relative to the mean leftover, open bins
        // should absorb it; when the item exceeds the mean leftover by a
        // wide margin, a fresh bin avoids fragmenting a good bin.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 28.0;
    } else if post_residual < 7 {
        score -= 10.0 - 0.5 * (6 - post_residual) as f64;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Two-step lookahead: post_residual holds next item twice with tiny remainder.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Harmonic reuse — residual that fits the next item k times exactly.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
    }

    // Reward residuals in common size buckets.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION: fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // MUTATION: next-item sink reservation — lock bins whose post-residual
    // will tightly hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // MUTATION: late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // MUTATION: pair-fit bonus — bin can hold item plus next item together.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // MUTATION: dead-space liquidity gate — reward sealing unusable leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // MUTATION: remaining-scarcity fresh-bin surcharge.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // MUTATION: item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION: near-tight existing fit — keep compacting, don't expand.
        if fitting_bins_count >= 2 && norm_pr < 0.08 && progress > 0.25 && progress < 0.75 {
            fresh_cost += 10.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation (refined: window widened, chain-aware).
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Residual-entropy compaction — awkward mid-band leftovers penalized
    // more strongly as mean residual shrinks (refined: weight scales with
    // how far above the mean the leftover sits, catching drift early).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins
    // (refined: cubic term rewards near-complete bins harder late-stream).
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation — lock bins whose post-residual will
    // tightly hold the next item (refined: window widened to 6, scaled
    // by scarcity of fitting bins).
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate — a bin whose post-residual is smaller than
    // the running mean residual is effectively "sealed" space; reward sealing
    // it now, but penalize leaving a leftover that is barely below the mean.
    // MUTATION: gate sharpened — sealing band widened to 0.7*mean and the
    // below-mean trap band tightened so near-mean leftovers get a stronger,
    // progress-scaled penalty that also scales with how many bins could fit
    // the item (fragmentation risk rises when alternatives exist).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.7 {
            score -= 3.0 * (1.0 - pr / (mr * 0.7)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.9 && pr < mr * 1.0 {
            let alt = (fitting_bins_count.min(4) as f64) * 0.25 + 0.5;
            score += 2.2 * (1.0 - (pr - mr * 0.9) / (mr * 0.1).max(1.0)) * (0.4 + 0.6 * progress) * alt;
        }
    }

    // MUTATION (new): two-item chain compaction — when this item plus the
    // next item exactly or nearly exhausts the bin, strongly prefer it; the
    // reward decays with the leftover after the chain and grows late-stream
    // when remaining capacity is the scarce resource.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual < bin_capacity {
        let chain_left = (bin_residual - item_size - next_item_size) as f64;
        let urgency = (1.0 - remaining / (total_items.max(1) as f64).max(1.0)).max(0.0);
        if chain_left == 0 {
            score -= 20.0 + 10.0 * urgency;
        } else if chain_left <= 8.0 {
            score -= 8.0 * (1.0 - chain_left / 8.0) * (0.5 + 0.5 * progress + 0.5 * urgency);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (new): chain-rescue fresh gate — when a fresh bin lets the
        // current item AND the next item land together cleanly (item + next
        // fits within the capacity with tiny leftover), opening a bin is
        // cheaper than fragmenting; scaled by how badly open bins would strand
        // the next item.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair <= cap && cap - pair <= 4.0
                && next_item_size > post_residual {
                fresh_cost -= 6.0 * (1.0 - (cap - pair) / 4.0) * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let fill = item_size as f64 / cap;
    let mr = mean_residual.max(1.0);

    // Dead space penalties
    if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 45.0;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            if rem == 0 {
                score -= 65.0;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 10 {
                score += 12.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            // Divisibility bonus: residual that cleanly hosts repeated next items.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic)
    let tight = post_frac;
    score += tight * tight * 36.0;
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - tight);

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - tight);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // MUTATION: fill-depth momentum — prefer absorbing items into the deepest
    // open bins, sharpened late in the stream (from best-known lineage).
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // MUTATION: next-item sink reservation — lock bins whose post-residual
    // will tightly hold the next item, scaled by scarcity of fitting bins.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tightness * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // MUTATION: dead-space liquidity gate — reward sealing bins whose leftover
    // falls well below the mean residual; penalize leftovers hovering just
    // under the mean (silently wasted capacity).
    if bin_residual != bin_capacity && post_residual > 0 {
        if (post_residual as f64) <= mr * 0.6 {
            score -= 2.0 * (1.0 - post_residual as f64 / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if post_residual as f64 > mr * 0.85 && (post_residual as f64) < mr {
            score += 1.5 * (1.0 - (post_residual as f64 - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION: late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        }
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 7.0;
        }
        // Late stream: fresh bins are more expensive since remaining items are few.
        fresh_cost += 8.0 * progress;

        // MUTATION: item-size vs. mean-residual fresh gate — small items
        // relative to mean leftover should go into open bins; large items
        // exceeding mean leftover by a wide margin justify a fresh bin.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mr;
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }

        // MUTATION: scarcity surcharge — late-stream fresh bins only for
        // rescue fits (huge item or huge next item).
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }

        // MUTATION: mean-residual-aware fresh gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (borrowed from best).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Residual-entropy compaction — awkward mid-band leftovers penalized.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer deepest bins, cubic term late-stream.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // MUTATION: dead-space liquidity gate (kept from parent line, retuned).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.5 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.8 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (new): mean-residual-normalized gap coupling — reward bins
    // whose leftover gap after placement is a near-exact multiple of the
    // running mean residual (those gaps are likely reusable), penalize
    // gaps that fall just below one mean residual (likely dead space).
    if bin_residual != bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let ratio = pr / mean_residual;
        let nearest = ratio.round();
        if nearest >= 1.0 && (ratio - nearest).abs() < 0.12 {
            score -= 2.0 * (nearest.min(3.0) / 3.0) * (0.4 + 0.6 * progress);
        } else if ratio < 0.95 && ratio > 0.4 {
            score += 1.2 * (0.95 - ratio) * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate handling (condensed from best, retuned).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (new): two-item chain gate — when item + next item would
        // fit a fresh bin exactly (or with <= 3 slack), opening a fresh bin
        // is attractive; otherwise penalize opening bins for medium items
        // when a fitting bin leaves only a small gap.
        if fitting_bins_count >= 1 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair <= cap && cap - pair <= 3.0 {
                fresh_cost -= 10.0 * (1.0 - (cap - pair) / 3.0) * (0.5 + 0.5 * progress);
            } else if fill > 0.3 && fill < 0.7 && progress < 0.5 {
                fresh_cost += 4.0 * (1.0 - progress * 2.0);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation (refined: window widened, chain-aware).
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Residual-entropy compaction — awkward mid-band leftovers penalized
    // more strongly as mean residual shrinks (refined: weight scales with
    // how far above the mean the leftover sits, catching drift early).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins
    // (refined: cubic term rewards near-complete bins harder late-stream).
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation — lock bins whose post-residual will
    // tightly hold the next item (refined: window widened to 6, scaled
    // by scarcity of fitting bins).
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate — a bin whose post-residual is smaller than
    // the running mean residual is effectively "sealed" space; reward
    // sealing it now, penalize leaving a leftover barely below the mean.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (new): dual-lookahead fragmentation guard — when neither the
    // next item NOR a hypothetical small item (mean residual proxy) can use
    // the post-residual, the leftover is genuinely stranded; penalize it
    // proportionally to how much capacity it strands. Conversely, when the
    // post-residual can chain-absorb the next item AND still leave a slot
    // near the mean residual, reward the bin as a "productive host".
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // MUTATION (new): compaction pressure term — as the stream progresses
    // and the mean residual shrinks, gently reward filling the bin whose
    // resulting post-residual lands closest to the *next* item's natural
    // slot (post_residual ≈ next_item_size), sharpening chain-packing
    // beyond the existing fixed-window bonuses.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (new): stranded-capacity fresh-bin gate — if opening a
        // fresh bin would strand the best open-bin post-residual (i.e. the
        // minimum achievable post_residual exceeds the mean residual by a
        // wide margin while the item is large), make the fresh bin cheaper;
        // if open bins would seal themselves tightly (post_residual tiny),
        // make the fresh bin expensive to protect consolidation.
        if fitting_bins_count >= 1 {
            let best_pr = post_residual as f64;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    score += 0.20 * (mean_residual - pr).abs() / cap;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }

    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        score += 1.5 * (pr / mean_residual.max(1.0)) * progress;
    }

    if bin_residual != bin_capacity && post_residual <= 4 && progress > 0.2 {
        score -= 5.0 * (1.0 - post_residual as f64 / 5.0) * progress;
    }

    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let gap = (bin_residual - item_size) as f64;
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0
        && post_residual != next_item_size {
        score -= 3.0 * progress;
    }

    if post_residual > 0 && post_residual < bin_capacity {
        let rr = post_residual;
        if rr % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if rr % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && mean_residual < 6.0 {
        score += 0.8 * (6.0 - mean_residual) * norm_pr * 10.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }

    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem >= 3 && rem <= 12 {
            score -= 2.0 * (1.0 - rem as f64 / 12.0) * (0.3 + 0.7 * progress);
        }
    }

    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let unusable = post_residual as f64;
        if unusable > mean_residual {
            let e = unusable - mean_residual;
            score += 0.10 * e * (0.5 + progress) + 0.03 * e * e / cap * (0.5 + progress);
        }
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        score -= 2.0 * (k.min(3) as f64) * (0.4 + 0.8 * progress);
    }

    if bin_residual != bin_capacity && post_residual >= 3 && post_residual <= 10
        && next_item_size > post_residual {
        score -= 1.8 * (1.0 - post_residual as f64 / 11.0) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == 0 && bin_residual % item_size.max(1) == 0
        && item_size < bin_residual {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let d = (pr - mean_residual).abs();
        if d <= 4.0 {
            score -= 2.5 * (1.0 - d / 4.0) * (0.4 + 0.6 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual {
        let e = pr - mean_residual.max(1.0);
        if e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
    }

    // Absorbable-residual lock-in.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 6.5 * (1.0 - slack as f64 / 4.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-band waste compounding.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > post_residual
        && post_residual as f64 > mean_residual * 1.2 && progress > 0.4 {
        let frozen = post_residual as f64 - mean_residual * 1.2;
        score += 0.08 * frozen * (progress - 0.4) * 2.0;
    }

    // Late-stream exact-fit escalation (refined: window widened, chain-aware).
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - post_residual as f64 / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Open-bin count-aware consolidation.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Residual-entropy compaction — awkward mid-band leftovers penalized
    // more strongly as mean residual shrinks.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation — lock bins whose post-residual will
    // tightly hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // MUTATION (gen 34a): two-step chain reservation — when the next item
    // fits and the *remaining* slack after it can still absorb a typical
    // follow-up item (mean residual proxy), reward this bin as a durable
    // chain host; if the chain leaves an awkward non-absorbable sliver,
    // damp the reward so we don't over-commit to one-step chains.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let mr = mean_residual.max(1.0);
        let after_chain = pr - next_item_size as f64;
        if after_chain >= mr * 0.8 {
            score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0)
                * (0.4 + 0.6 * progress);
        } else if after_chain > 0.0 && after_chain < mr * 0.35 && after_chain > 1.5 {
            score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 34b): residual-harvest triage — a leftover whose size is
    // a near-multiple of the mean residual is likely to be harvested by
    // future small items; reward keeping such bins open. A leftover in the
    // "dead zone" just below the smallest plausible item (mean residual)
    // is nearly unsalvageable; penalize proportionally to its size.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 && ratio.round() >= 1.0 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.4 {
            let e = post_residual as f64 - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && post_residual as f64 > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && post_residual as f64 > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - post_residual as f64 / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = post_residual as f64;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 34c): fresh-bin harvestability gate — if the best
        // open-bin post-residual is a near-multiple of the mean residual
        // (likely harvestable by future items), opening a fresh bin wastes
        // that latent value; surcharge the fresh bin. If the best leftover
        // sits in the dead zone just under the mean residual, it will
        // likely never be used, so discount the fresh bin.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = post_residual as f64 / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.07 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let fill = item_size as f64 / cap;
    let mr = mean_residual.max(1.0);

    // Dead space penalties (sharpened tiers from best-known lineage)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Exact-fill anticipation
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }
    if post_residual > 0 && (post_residual % 5 == 0) {
        score -= 1.5 * progress;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else if rem < 10 {
                score += 12.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Multi-step chain fits
            if post_residual >= next_item_size * 2 {
                let rem3 = post_residual - next_item_size * 2;
                if rem3 <= 4 {
                    score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
                }
            }
            if post_residual >= next_item_size * 3 {
                let rem4 = post_residual - next_item_size * 3;
                if rem4 <= 6 {
                    score -= 4.0 * (1.0 - rem4 as f64 / 6.0) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += post_frac * 12.0 * if dead { 2.5 } else { 1.0 };
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
        }
        // Near-miss lookahead
        if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6) {
            score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
        }
        // Pairing with next item
        if post_residual >= next_item_size {
            let pair = item_size + next_item_size;
            if bin_residual >= pair {
                score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic)
    let tight = post_frac;
    score += tight * tight * 36.0;
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - tight);

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - tight);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
        if slack == 0 {
            score -= 5.0;
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest open bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation — scarcity-scaled.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tightness * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard (from best lineage).
    if bin_residual != bin_capacity && post_residual > 0 {
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 7.0;
        }
        fresh_cost += 8.0 * progress;

        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mr;
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }

        // Scarcity surcharge.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }

        // Mean-residual-aware fresh gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }

        // Fresh-bin harvestability gate: opening a bin whose best leftover would
        // sit near a multiple of the mean residual is wasteful; leftovers in the
        // sub-mean band are harvestable and slightly cheaper.
        if fitting_bins_count >= 1 {
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }

        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            if pr > mr * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * ((pr - mr * 1.6).min(10.0)) * (0.4 + 0.6 * progress);
            } else if pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }

        // Tiny leftover open bins should be sealed, not abandoned.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let fill = item_size as f64 / cap;
    let mr = mean_residual.max(1.0);

    // Tiered dead-space handling (combined with best-fit tiers).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        if gap <= 3.0 {
            score -= 16.0 - 4.0 * gap;
        } else if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        } else if gap > mr * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as u32 == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 45.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else if rem < 10 {
                score += 6.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Multi-item divisibility compaction.
            let k = post_residual / next_item_size;
            if k >= 2 {
                score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 6.0 {
                score += 4.0 * (1.0 - miss / 7.0);
            }
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let after_chain = pr - next_item_size as f64;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
        // Pair-completion bonus.
        if next_item_size == item_size && post_residual == item_size {
            score -= 8.0;
        }
        if post_residual >= next_item_size {
            let pair = item_size + next_item_size;
            if bin_residual >= pair && bin_residual < bin_capacity {
                score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Tight-fit sharpening (quadratic, progress-sharpened)
    let tight = post_frac;
    score += tight * tight * (36.0 + 20.0 * progress);
    score -= (item_size as f64 / cap) * 10.0 - 2.5 * fill * (1.0 - fill);

    // Fragmented-bin penalty unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - tight);

    // Consolidation pressure
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - tight);
