    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Two-item lookahead: reward small reusable slack
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
