    // Next-item sink reservation
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tightness * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate
    if bin_residual != bin_capacity && post_residual > 0 {
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Late-stream exact-fit escalation
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate
    if bin_residual == bin_capacity {
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 7.0;
        }
        fresh_cost += 8.0 * progress;

        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mr;
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }

        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }

        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Best-fit lineage: harvestability gate — opening a fresh bin is more
        // attractive when the best open-bin leftover is awkward (not a clean
        // multiple of mean residual) and the item is large.
        if fitting_bins_count >= 1 {
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
            if pr > mr * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * ((pr - mr * 1.6).min(10.0)) * (0.4 + 0.6 * progress);
            }
            if pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
