                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack — if open bins already
        // hoard large total leftover, opening a new bin is relatively cheaper
        // than compounding fragmentation; if slack is tight, surcharge.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when the current item could instead finish
        // an open bin completely (post_residual == 0 in some open bin).
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate — if the mean residual is drifting
        // upward (fragmenting fleet), opening a new bin resets the fleet to a
        // single large leftover, which is cheaper; if the fleet is tight, keep
        // compacting instead.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // NEW (gen 36): fresh-bin chain-completion gate — if placing this item
        // in an open bin would leave a residual that exactly absorbs the next
        // item (post_residual == next_item_size), a fresh bin is clearly worse;
        // if no open bin can chain the next item, opening fresh is cheaper.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (sharper near-perfect tiers).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when current item could finish an open bin.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 36): fresh-bin two-item compaction gate — if a fresh bin
        // could absorb this item AND the next item together, opening fresh is
        // cheaper than fragmenting an open bin; but if an open bin already
        // chains both items exactly, keep compacting.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair <= bin_capacity && post_residual == pair.saturating_sub(item_size) {
                fresh_cost += 6.0 * (0.5 + 0.5 * progress);
            }
            if pr > 0.0 && pr < 4.0 && fill < 0.5 {
                fresh_cost += 5.0;
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let post_frac = pr / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let fill = item_size as f64 / cap;
    let mr = mean_residual.max(1.0);

    // Dead space penalties (sharpened tiers)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Exact-fill anticipation
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        if gap <= 3.0 {
            score -= 16.0 - 4.0 * gap;
        }
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 30.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else if rem < 10 {
                score += 12.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Multi-step chain fits
            if post_residual >= next_item_size * 2 {
                let rem2 = post_residual - next_item_size * 2;
                if rem2 <= 4 {
                    score -= 3.5 * (1.0 - rem2 as f64 / 4.0) * (0.4 + 0.6 * progress);
                }
            }
            if post_residual >= next_item_size * 3 {
                let rem3 = post_residual - next_item_size * 3;
                if rem3 <= 6 {
                    score -= 4.0 * (1.0 - rem3 as f64 / 6.0) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
            // Near-miss lookahead: next item slightly exceeds residual
            if next_item_size - post_residual <= 6 {
                score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
            }
        }
        // Two-step chain reservation
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let after_chain = pr - next_item_size as f64;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 10.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic)
    let tight = post_frac;
    score += tight * tight * 36.0;
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - tight);

    // Residual-band gap shaping
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - tight);
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_of(post_frac)) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest open bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tightness * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space-ratio targeted compaction — graded reward for residuals that
    // track the stream's typical leftover, graded penalty for near-dead ones.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * ((-dev - 0.25).min(1.5)) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Fleet-wide residual collapse — reward placements collapsing toward
    // integer multiples of the mean residual; penalize awkward band above it.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - tight) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            fresh_cost -= 7.0;
        }
        fresh_cost += 8.0 * progress;

        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mr;
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }

        // Scarcity surcharge.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }

        // Mean-residual-aware fresh gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }

        // Chain-completion gate — if an open bin would exactly absorb the next
        // item, fresh is clearly worse; if no open bin can chain, fresh is cheaper.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }

        // Discourage fresh when an open bin could be finished completely.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }

        // Aggregate-slack fresh gate.
        if fitting_bins_count >= 1 {
            let agg = mr * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }

        // Harvestability fresh gate.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }

        // Late-stream fresh cost.
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((pr) - mean_residual).abs() * 0.05;

    score
}

#[inline]
fn norm_of(x: f64) -> f64 {
    (1.0 - x).max(0.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let mr = mean_residual.max(1.0);

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if nr == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = nr / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            let k = post_residual / next_item_size;
            if k >= 2 {
                score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
            }
        } else {
            let dead = norm_pr < 0.12 && nr > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Near-miss: next item just exceeds residual (awkward gap).
        if nr > pr && pr - nr <= -1.0 && (next_item_size - post_residual) as f64 <= 6.0 {
            let miss = (next_item_size - post_residual) as f64;
            score += 4.5 * (1.0 - miss / 7.0) * (0.5 + 0.5 * progress);
        }
        if nr > 0.0 && pr >= nr && (pr - nr) <= 5.0 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && (pr - nr * 2.0) <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            if pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Aggregate open-bin slack gate.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when an open bin would finish completely.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // Gen 36 mutation: chain-harvest fresh gate — if the best open bin would
        // leave a residual divisible by the next item (predictable reuse),
        // opening fresh is strongly worse; if it strands an awkward band just
        // above the mean residual, fresh is comparatively cheaper.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after == 0 {
                fresh_cost += 12.0 * (0.5 + 0.5 * progress);
            } else if (after as f64) < mr * 0.35 {
                fresh_cost += 4.0 * (1.0 - after as f64 / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = post_residual as f64;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let fill = item_size as f64 / cap;
    let mr = mean_residual.max(1.0);

    // Dead space penalties (tiered, sharpened)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Exact-fill anticipation (borrowed from best lineage)
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Multi-step chain fits
            if post_residual >= next_item_size * 2 {
                let rem2 = post_residual - next_item_size * 2;
                if rem2 <= 4 {
                    score -= 3.5 * (1.0 - rem2 as f64 / 4.0) * (0.4 + 0.6 * progress);
                }
            }
            if post_residual >= next_item_size * 3 {
                let rem3 = post_residual - next_item_size * 3;
                if rem3 <= 6 {
                    score -= 4.0 * (1.0 - rem3 as f64 / 6.0) * (0.5 + 0.5 * progress);
                }
            }
            // Chain leftover tracks mean residual: reusable shape.
            let after_chain = pr - nr;
            if (after_chain - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (after_chain - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if after_chain < 2.0 {
                score -= 5.0 * (1.0 - after_chain / 2.0) * (0.5 + 0.5 * progress);
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
            // Near-miss penalty: residual just below next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 6.0 {
                score += (5.0 - miss) * (0.6 + 0.8 * progress);
            } else if miss > 8.0 {
                score += 0.35 * (miss - 8.0).min(20.0) * (0.3 + 0.7 * progress);
            }
        }
        // Pair-completion bonus.
        if next_item_size == item_size && post_residual == item_size {
            score -= 8.0;
        }
        // Pairing with next item.
        let pair = item_size + next_item_size;
        if bin_residual >= pair && bin_residual < bin_capacity {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic, progress-sharpened)
    score += post_frac * post_frac * (36.0 + 5.0 * progress);
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large (fragmented) unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - post_frac);

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mr * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - post_frac);
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - post_frac);
    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Two-item lookahead: reward residual that can host the next item plus a
    // small follow-up, favoring reusable leftover shapes.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest open bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation — lock bins whose post-residual will tightly
    // hold the next item, scaled by scarcity of fitting bins.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tightness * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space-ratio targeted compaction — attack residual variance directly.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate: discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        let next_large = next_item_size as f64 > 0.5 * cap;
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + (item_size as f64 / cap) * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_item_size > 0 && bin_residual >= next_item_size && next_item_size as f64 > 0.5 * cap {
                fresh_cost -= 18.0;
            }
        }
        if next_item_size > 0 && next_large {
            fresh_cost -= 7.0;
        }
        fresh_cost += 8.0 * progress;

        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mr;
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }

        // Scarcity surcharge — late-stream fresh bins only for rescue fits.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }

        // Mean-residual-aware fresh gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }

        // Chain-completion gate — if an open bin would exactly absorb the next
        // item, a fresh bin is clearly worse; if no open bin can chain, fresh
        // is relatively cheaper.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }

        // Discourage fresh bins when an open bin would be finished completely.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }

        // Fresh-bin gate on aggregate open-bin slack.
        if fitting_bins_count >= 1 {
            let agg = mr * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (sharper near-perfect tiers).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position (strengthened).
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (sharper near-perfect tiers).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Two-step chain fits (borrowed from best).
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
            let rem3 = post_residual - next_item_size * 2;
            if rem3 <= 4 {
                score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size * 3 {
            let rem = post_residual - next_item_size * 3;
            if rem <= 6 {
                score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
            }
        }
        // Chain reservation: after absorbing the next item, leftover should
        // either be large enough to absorb the mean-sized future item or tiny.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
        // Harmonic reuse — residual that fits the next item k times exactly.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
            if k >= 2 {
                score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position (strengthened).
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction (directly attacks dead space).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse (gen 36 feature).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            if pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Aggregate open-bin slack gate.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when an open bin would finish completely.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // GEN 37: fresh-bin penalty when an open bin would end with residual
        // in a highly reusable low band (<= 6) — keep compacting instead.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 6 {
            fresh_cost += 4.0 * (1.0 - pr / 7.0) * (0.4 + 0.6 * progress);
        }
        // GEN 37: fresh-bin discount when every existing fit strands a residual
        // that no next-item chain can absorb and the item is deep-filling.
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && post_residual > 6 && fill > 0.6 {
            fresh_cost -= 3.0 * progress;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 4.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 28.0;
    } else if post_residual < 7 {
        score -= 10.0 - 0.5 * (6 - post_residual) as f64;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        // Two-step lookahead: near-filling leftovers.
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        // Two-item chain: pr >= 2*next with small remainder.
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Conserve low residuals for future small items.
        if post_residual < next_item_size {
            score += 4.0;
        }
        // Reward bins whose post_residual can host the upcoming demand.
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        // Two-item lookahead: post_residual fits next item plus tiny remainder.
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Harmonic reuse — residual that fits the next item k times exactly.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
        }
        // Chain reservation: after absorbing the next item, leftover tracks
        // the stream's typical leftover (high reuse) vs. stranded sliver.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after = pr - nr;
            if after >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after > 1.5 && after < mr * 0.35 {
                score += 1.2 * (1.0 - after / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * ((-dev - 0.25).min(1.5)) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            if pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Aggregate-slack fresh-bin gate.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when an open bin could be finished completely.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 37): combined fit-quality fresh gate — when the best
        // existing fit is genuinely tight (post-residual below the mean
        // leftover), compaction beats expansion; when every fit strands a
        // large dead band, opening fresh is cheaper.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            if pr < mr * 0.7 {
                fresh_cost += 6.0 * (1.0 - pr / (mr * 0.7)) * (0.4 + 0.6 * progress);
            } else if pr > mr * 1.8 && fill > 0.35 {
                fresh_cost -= 3.0 * ((pr - mr * 1.8) / mr).min(2.0) * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 37): mid-stream dead-zone fresh gate — all fits leaving
        // residuals in the awkward 8..20 band make fresh cheaper.
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (pr - 8.0) / 12.0);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (compaction core).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling with progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if nr == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = nr / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && nr > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Fill-depth momentum — prefer deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Near-miss lookahead.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_large {
                fresh_cost -= 14.0;
            }
        }
        if fill > 0.6 {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            }
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when an open bin would finish completely.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // Aggregate-slack gate.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position (strengthened).
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure — when open bins carry lots of
    // aggregate leftover, push harder toward bins that would end near-empty.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item — a "near-usable"
    // gap that wastes capacity; prefer bins whose post-residual clears it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction — compare the post-residual
    // against the *expected* leftover of the stream; bins whose post-residual
    // deviates far below the mean are near-dead and get a graded penalty,
    // while bins absorbing the mean-sized leftover get a graded reward. This
    // directly attacks residual variance (Sigma_res) and dead-space ratio.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            // Residual much smaller than typical leftover: hard to reuse.
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            // Residual tracks the stream's typical leftover: highly reusable.
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        // Fractional dead-space of the whole bin after placement.
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness — when residuals across bins are widely
    // spread, favor placements that collapse a bin toward 0 leftover; when
    // residuals are tight, mild preference for exact chain fits.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            // This bin becomes the tightest of the fleet — good compaction.
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // (gen 36) fleet-wide residual collapse — reward placements that drive a
    // bin's post-residual to an integer multiple of the mean residual
    // (predictable reuse), and penalize placements that strand residual in the
    // awkward band just above the mean (high fragmentation risk).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // NEW (gen 37): residual-variance collapse — the diagnosed weakness is
    // residual spread. Reward placements whose post-residual lands close to
    // the fleet's mean residual with graded tightness, and add an extra
    // quadratic penalty on post-residuals far above the mean when the fleet
    // already carries many open bins (fragmentation compounding).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let rel = pr / mr;
        if rel >= 0.85 && rel <= 1.25 {
            score -= 1.6 * (1.0 - (rel - 1.0).abs() / 0.25) * (0.4 + 0.6 * progress);
        }
        if open_bins_count >= 4 {
            let over = (pr - mr * 1.5).max(0.0);
            score += 0.05 * over * over / mr.max(1.0) * (0.3 + 0.7 * progress);
        }
    }

    // NEW (gen 37): perfect-closure ladder — escalate the reward for driving
    // a bin to (near-)zero leftover as the stream progresses, since late
    // closures remove residual variance permanently.
    if bin_residual != bin_capacity && post_residual > 0 {
        let ladder = if post_residual == 1 {
            10.0
        } else if post_residual == 2 {
            6.0
        } else if post_residual <= 5 {
            3.0
        } else {
            0.0
        };
        score -= ladder * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack — if open bins already
        // hoard large total leftover, opening a new bin is relatively cheaper
        // than compounding fragmentation; if slack is tight, surcharge.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when the current item could instead finish
        // an open bin completely (post_residual == 0 in some open bin).
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate — if the mean residual is drifting
        // upward (fragmenting fleet), opening a new bin resets the fleet to a
        // single large leftover, which is cheaper; if the fleet is tight, keep
        // compacting instead.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate — if placing this item in an open
        // bin would leave a residual that exactly absorbs the next item
        // (post_residual == next_item_size), a fresh bin is clearly worse;
        // if no open bin can chain the next item, opening fresh is cheaper.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 37): fresh-bin variance gate — when the fleet's mean
        // residual is small (tight fleet), opening a fresh bin is a variance
        // reset that costs a whole extra bin: surcharge it. When the fleet is
        // fragmented AND the item is small relative to the mean residual,
        // opening fresh is comparatively cheap.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.08 && fill < 0.35 {
                fresh_cost += 6.0 * (0.08 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            }
            if mrn > 0.15 && fill < 0.3 && progress > 0.4 {
                fresh_cost -= 3.0 * (mrn - 0.15) * 15.0 * (progress - 0.4);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items - step_index.min(total_items)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (gen 37: sharpened zero/near-zero tier).
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual < 6 {
        score -= 15.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position (strengthened).
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // NEW (gen 37): two-item lookahead harvest — when the next item fits the
    // post-residual and the item after that is likely near the mean residual,
    // reward placements whose post-residual can absorb BOTH (chain of two),
    // and penalize placements that strand a residual that can absorb neither.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let mr = mean_residual.max(1.0);
        let nr = next_item_size as f64;
        if pr >= nr {
            let after1 = pr - nr;
            if after1 >= mr * 0.9 && after1 <= mr * 1.4 {
                score -= 2.6 * (1.0 - (after1 - mr * 0.9).abs() / (mr * 0.5).max(1.0))
                    * (0.4 + 0.6 * progress);
            }
        } else if pr < mr * 0.5 && nr > pr * 1.5 {
            score += 1.2 * (1.0 - pr / (mr * 0.5).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when the current item could finish an open bin.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 37): fresh-bin two-item harvest gate — if an open bin could
        // chain the next item AND land within the mean-residual harvest band
        // afterwards, a fresh bin is clearly worse; strengthen the surcharge.
        if fitting_bins_count >= 1 && next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= mean_residual.max(1.0) * 1.3 {
                fresh_cost += 3.0 * (1.0 - after / (mean_residual.max(1.0) * 1.3))
                    * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let post_frac = post_residual as f64 / cap;
    let post_mod = post_residual % 10;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let fill = item_size as f64 / cap;
    let mr = mean_residual.max(1.0);

    // Dead space penalties (fine-grained tiers)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 10 {
        score += 65.0 - post_frac * 30.0;
    } else if post_residual < 20 {
        score += 16.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Harmonic leftovers
    if post_residual >= 10 && post_mod == 0 {
        score -= 9.0;
    }

    // Exact-fill anticipation
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Lookahead compatibility with chained-fill quality
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 40.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 20.0 + 6.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 7.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Multi-step chain fits
            if post_residual >= next_item_size * 2 {
                let rem2 = post_residual - next_item_size * 2;
                if rem2 <= 4 {
                    score -= 3.5 * (1.0 - rem2 as f64 / 4.0) * (0.4 + 0.6 * progress);
                }
            }
            if post_residual >= next_item_size * 3 {
                let rem3 = post_residual - next_item_size * 3;
                if rem3 <= 6 {
                    score -= 4.0 * (1.0 - rem3 as f64 / 6.0) * (0.5 + 0.5 * progress);
                }
            }
            // Chain-left matches mean residual: predictable reuse
            let after_chain = pr - nr;
            if (after_chain - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (after_chain - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if after_chain < 2.0 {
                score -= 5.0 * (1.0 - after_chain / 2.0) * (0.5 + 0.5 * progress);
            }
        } else {
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            score += post_frac * 12.0;
            if waste > 0.05 * cap {
                score += 0.09 * waste;
            }
        }
        // Near-miss lookahead: next item slightly exceeds residual
        if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6) {
            score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
        }
        // Pairing with next item
        if post_residual >= next_item_size {
            let pair = item_size + next_item_size;
            if bin_residual >= pair {
                score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
            }
        }
        // Two-item lookahead: small usable slack
        if pr - nr > 0.0 && pr - nr <= 12.0 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Tight-fit sharpening (best-fit style, quadratic with progress sharpening)
    let tight = post_frac;
    score += tight * tight * (36.0 + 5.0 * progress);
    score -= (item_size as f64 / cap) * 10.0;

    // Penalize bins whose residual is already large unless fit is tight
    let res_frac = bin_residual as f64 / cap;
    score += 4.5 * res_frac * (1.0 - tight);

    // Consolidation pressure when many bins are open
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.8 * (1.0 - tight);
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling
    score += 0.03 * mean_residual * (1.0 - tight);

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation — lock bins whose post-residual tightly holds the next item.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tightness * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate
    if bin_residual != bin_capacity && post_residual > 0 {
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space-ratio targeted compaction — attack residual variance directly.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Absolute dead-space penalty scaled by stream position
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Late-stream exact-fit escalation
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 40.0
            + 14.0 * (fitting_bins_count.min(6) as f64)
            - 14.0 * (1.0 - progress)
            + fill * 20.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 12.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                fresh_cost -= 3.0;
            }
            if next_large {
                fresh_cost -= 14.0;
            }
        }
        if next_large {
            fresh_cost -= 7.0;
        }
        fresh_cost += 8.0 * progress;

        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mr;
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }

        // Scarcity surcharge
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }

        // Mean-residual-aware fresh gate
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Aggregate-slack fresh gate
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // Discourage fresh bins when an open bin could be finished exactly
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin gate: near-zero post residual means an open bin is nearly sealed
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 12.0;
        }
        score += fresh_cost;
    }

    // Mild tie-break toward nearly-full bins
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position (strengthened).
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure — when open bins carry lots of
    // aggregate leftover, push harder toward bins that would end near-empty.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item — a "near-usable"
    // gap that wastes capacity; prefer bins whose post-residual clears it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction — compare the post-residual
    // against the *expected* leftover of the stream; bins whose post-residual
    // deviates far below the mean are near-dead and get a graded penalty,
    // while bins absorbing the mean-sized leftover get a graded reward. This
    // directly attacks residual variance (Sigma_res) and dead-space ratio.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            // Residual much smaller than typical leftover: hard to reuse.
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            // Residual tracks the stream's typical leftover: highly reusable.
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        // Fractional dead-space of the whole bin after placement.
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness — when residuals across bins are widely
    // spread, favor placements that collapse a bin toward 0 leftover; when
    // residuals are tight, mild preference for exact chain fits.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            // This bin becomes the tightest of the fleet — good compaction.
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse — when the aggregate open-bin
    // slack is small relative to capacity, strongly reward placements that
    // drive a bin's post-residual to an integer multiple of the mean residual
    // (predictable reuse), and penalize placements that strand residual in the
    // awkward band just above the mean (high fragmentation risk).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // NEW (gen 38): residual-variance sink — prefer placements that bring the
    // fleet's post-residual distribution closer to a single reusable value.
    // If the item would land in a bin whose post-residual is near the *next*
    // item size exactly, that bin becomes a perfect sink; reward sharply.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let sink_err = (pr - next_item_size as f64).abs();
        if sink_err <= 2.0 {
            score -= 4.5 * (1.0 - sink_err / 2.0) * (0.45 + 0.55 * progress);
        }
        // Penalize post-residuals in the "unreachable band": larger than the
        // mean residual but smaller than the next item — likely stranded.
        let mr = mean_residual.max(1.0);
        if pr > mr * 1.15 && next_item_size as f64 > pr {
            score += 1.1 * ((pr - mr * 1.15) / mr).min(1.5) * (0.4 + 0.6 * progress);
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack — if open bins already
        // hoard large total leftover, opening a new bin is relatively cheaper
        // than compounding fragmentation; if slack is tight, surcharge.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when the current item could instead finish
        // an open bin completely (post_residual == 0 in some open bin).
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate — if the mean residual is drifting
        // upward (fragmenting fleet), opening a new bin resets the fleet to a
        // single large leftover, which is cheaper; if the fleet is tight, keep
        // compacting instead.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate — if placing this item
        // in an open bin would leave a residual that exactly absorbs the next
        // item (post_residual == next_item_size), a fresh bin is clearly worse;
        // if no open bin can chain the next item, opening fresh is cheaper.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 38): fresh-bin variance gate — when the fleet's mean
        // residual is moderate and the best available open-bin post-residual
        // would land far from the next item (stranded slack), opening a fresh
        // bin preserves a large harvestable residual; reward that trade-off.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            let sink_err = (pr - next_item_size as f64).abs();
            if sink_err > mr * 1.5 && fill > 0.55 {
                fresh_cost -= 2.5 * ((sink_err - mr * 1.5) / mr).min(2.0) * (0.4 + 0.6 * progress);
            } else if sink_err <= mr * 0.5 {
                fresh_cost += 5.0 * (1.0 - sink_err / (mr * 0.5).max(1.0)) * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position (strengthened).
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let e = pr - mean_residual.max(1.0);
        if next_item_size > post_residual && e > 1.5 {
            score += 0.06 * e * e * (0.2 + 0.8 * progress) / cap * 10.0;
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Stranded-forecast dead-space sharpening.
    if bin_residual != bin_capacity && post_residual > 8 && next_item_size > 0
        && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded <= 8.0 {
            score += 1.5 + 0.45 * (8.0 - stranded) * (0.5 + progress);
        }
    }
    if bin_residual != bin_capacity && post_residual >= 14 && post_residual < 26
        && next_item_size > post_residual {
        score += 1.2 + 0.08 * (post_residual - 14) as f64 * (0.5 + progress);
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure — when open bins carry lots of
    // aggregate leftover, push harder toward bins that would end near-empty.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item — a "near-usable"
    // gap that wastes capacity; prefer bins whose post-residual clears it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction — compare the post-residual
    // against the *expected* leftover of the stream; bins whose post-residual
    // deviates far below the mean are near-dead and get a graded penalty,
    // while bins absorbing the mean-sized leftover get a graded reward.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            // Residual much smaller than typical leftover: hard to reuse.
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            // Residual tracks the stream's typical leftover: highly reusable.
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        // Fractional dead-space of the whole bin after placement.
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness — when residuals across bins are widely
    // spread, favor placements that collapse a bin toward 0 leftover; when
    // residuals are tight, mild preference for exact chain fits.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            // This bin becomes the tightest of the fleet — good compaction.
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse — reward placements that drive a bin's
    // post-residual to an integer multiple of the mean residual (predictable
    // reuse), and penalize placements that strand residual in the awkward
    // band just above the mean (high fragmentation risk).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // NEW (gen 38): two-item lookahead compaction — when the next item fits
    // the post-residual and the item after that is plausibly the same size
    // (stream regularity), a residual exactly equal to next_item_size is a
    // perfect double-harvest; deepen the existing chain bonus in that case.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.15 {
        let regular = (mean_residual - next_item_size as f64).abs() < mean_residual * 0.35;
        score -= if regular { 6.0 } else { 2.5 } * (0.5 + 0.5 * progress);
    }

    // NEW (gen 38): dead-space budget cap — a post-residual larger than what
    // the mean leftover could ever absorb is pure waste; penalize it more
    // sharply as the fleet's aggregate slack shrinks (less room to hide it).
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let tight = (1.0 - (agg / (cap * 10.0)).min(1.0)) * (0.5 + 0.5 * progress);
        if pr > mr * 2.0 {
            score += 1.1 * ((pr - mr * 2.0) / mr).min(3.0) * tight;
        }
        // Reward placements that leave the fleet's tightest residual yet.
        if pr < mr * 0.45 && pr > 0.0 && post_residual <= 8 {
            score -= 1.6 * (1.0 - pr / (mr * 0.45)) * tight;
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when the current item could instead finish
        // an open bin completely.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 38): fresh-bin dead-space escape valve — if every fitting
        // open bin would strand a post-residual far above the mean leftover
        // (unharvestable waste), opening fresh is comparatively cheap; but if
        // some open bin would finish near-exactly, fresh is very expensive.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            if pr > mr * 2.2 && fill > 0.35 {
                fresh_cost -= 2.5 * ((pr - mr * 2.2) / mr).min(3.0) * (0.4 + 0.6 * progress);
            }
            if pr <= mr * 0.5 {
                fresh_cost += 3.0 * (1.0 - pr / (mr * 0.5).max(1.0)) * (0.5 + 0.5 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // Two-item lookahead compaction — exact double-harvest residuals.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.15 {
        let regular = (mean_residual - next_item_size as f64).abs() < mean_residual * 0.35;
        score -= if regular { 6.0 } else { 2.5 } * (0.5 + 0.5 * progress);
    }

    // Dead-space budget cap — penalize unharvestable waste, reward tightest residuals.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let tight = (1.0 - (agg / (cap * 10.0)).min(1.0)) * (0.5 + 0.5 * progress);
        if pr > mr * 2.0 {
            score += 1.1 * ((pr - mr * 2.0) / mr).min(3.0) * tight;
        }
        if pr < mr * 0.45 && pr > 0.0 && post_residual <= 8 {
            score -= 1.6 * (1.0 - pr / (mr * 0.45)) * tight;
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when the current item could finish an open bin.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin dead-space escape valve.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            if pr > mr * 2.2 && fill > 0.35 {
                fresh_cost -= 2.5 * ((pr - mr * 2.2) / mr).min(3.0) * (0.4 + 0.6 * progress);
            }
            if pr <= mr * 0.5 {
                fresh_cost += 3.0 * (1.0 - pr / (mr * 0.5).max(1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // NEW (gen 38): fresh-bin exact-fit lockout — if any open bin would be
        // filled to within 2 units, opening a fresh bin is strongly penalized.
        if fitting_bins_count >= 1 && post_residual <= 2 {
            fresh_cost += 9.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
        }
        // NEW (gen 38): fresh-bin cheapening when item + next item would exactly
        // fill a fresh bin (perfect two-item packing) and no open bin pairs well.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= cap * 0.98
            && fitting_bins_count >= 1
            && post_residual as f64 > cap - (item_size + next_item_size) as f64 {
            fresh_cost -= 7.0;
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let mr = mean_residual.max(1.0);

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if nr == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = nr / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Chain leaves a residual close to the mean (reusable later).
            let after = pr - nr;
            if after >= mr * 0.8 && after <= mr * 1.3 {
                score -= 3.5 * (1.0 - (after - mr * 0.8).max(0.0) / (mr * 0.5).max(1.0))
                    * (0.4 + 0.6 * progress);
            } else if after > 1.5 && after < mr * 0.35 {
                score += 1.2 * (1.0 - after / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
            // Two-step chain fits.
            if pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
                score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
            }
            if post_residual >= next_item_size * 3 {
                let rem3 = post_residual - next_item_size * 3;
                if rem3 <= 6 {
                    score -= 4.0 * (1.0 - rem3 as f64 / 6.0) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let dead = norm_pr < 0.12 && nr > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
            // Near-miss: next item slightly exceeds residual.
            let miss = nr - pr;
            if miss <= 6.0 {
                score += 4.0 * (1.0 - miss / 7.0);
            }
            if miss <= 10.0 && fitting_bins_count >= 2 {
                score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
            }
        }
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
            // Shortfall penalty for large unusable gaps.
            let shortfall = (next_item_size - post_residual) as f64;
            if shortfall > 8.0 {
                score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
            }
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        // Harmonic reuse: residual fits next item k times exactly.
        if post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            if rem <= 2 {
                score -= 5.0 * (1.0 - rem as f64 / 3.0) * (0.6 + 0.4 * progress);
            }
            if k >= 2 {
                score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }
    // Two-item lookahead compaction — exact double-harvest residuals.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.15 {
        let regular = (mean_residual - next_item_size as f64).abs() < mean_residual * 0.35;
        score -= if regular { 6.0 } else { 2.5 } * (0.5 + 0.5 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mr * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Common size bucket rewards.
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 || post_residual % 25 == 0 {
            score -= 4.0 * (0.5 + 0.5 * progress);
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Stranding / mean-residual drift shaping.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let nr = next_item_size as f64;
        if pr > 8.0 && pr < 30.0 && nr > pr && nr < pr + 12.0 {
            let tightness = 1.0 - (nr - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        // Fresh bin expensive when an open bin is a near-perfect fit.
        if fitting_bins_count >= 1 && norm_pr < 0.05 {
            fresh_cost += 8.0 * (0.05 - norm_pr) * 20.0;
        }
        // Fresh bin expensive when the current item would finish an open bin.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh bin expensive when post_residual <= 2 (near-exact fits exist).
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 12.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
        }
        // Fresh bin expensive when post_residual matches next item exactly.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual == next_item_size {
            fresh_cost += 9.0 + 5.0 * progress;
        }
        // Fresh bin cheaper when the item nearly fills it exactly.
        if fill > 0.85 {
            fresh_cost -= 9.0 * (fill - 0.85) * 10.0;
        }
        // Fresh bin cheaper when item + next item would exactly fill a fresh bin.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= cap * 0.98
            && fitting_bins_count >= 1
            && pr > cap - (item_size + next_item_size) as f64 {
            fresh_cost -= 7.0;
        }
        // Fresh bin cheaper when every fit leaves an awkward mid-band gap.
        if fitting_bins_count >= 2 && progress > 0.25 && progress < 0.75
            && post_residual >= 8 && post_residual <= 20 {
            fresh_cost -= 6.0 * (1.0 - (post_residual as f64 - 8.0) / 12.0);
        }
        // Fresh bin cheaper late-stream for large items.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Mean-residual-aware fresh gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Stranded-capacity fresh gate.
        if fitting_bins_count >= 1 {
            if pr > mr * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (pr - mr * 1.6).min(10.0) * (0.4 + 0.6 * progress);
            }
        }
        // Aggregate open-bin slack gate.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual < next_item_size {
            score += 4.0;
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr && (pr - nr) as u32 <= 5 {
            score -= 3.0 * (1.0 - (pr - nr) / 5.0);
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Two-step chain reservation.
        if post_residual >= next_item_size && bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            let after_chain = pr - nr;
            if after_chain >= mr * 0.8 {
                score -= 3.5 * (1.0 - (after_chain - mr * 0.8).min(8.0) / 8.0) * (0.4 + 0.6 * progress);
            } else if after_chain > 1.5 && after_chain < mr * 0.35 {
                score += 1.2 * (1.0 - after_chain / (mr * 0.35)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
        if gap > mean_residual.max(1.0) * 1.5 && gap > 8.0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 4 && progress > 0.5 {
        score += (open_bins_count as f64) * 0.4 * progress;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Global slack coupling and early tightness pressure.
    score += 0.02 * mean_residual * (1.0 - norm_pr);
    score += norm_pr * norm_pr * (6.0 * (1.0 - progress));

    // Dead-space fragmentation guards.
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 2.0 + 0.5 * (open_bins_count.min(10) as f64);
    }
    if progress > 0.6 && post_residual > 20 && post_residual < next_item_size {
        score += 1.5 + 2.5 * progress;
    }

    // Absolute dead-space penalty scaled by stream position.
    if post_residual > 22 && bin_residual < bin_capacity {
        score += 0.09 * (post_residual - 22) as f64 * (0.4 + 0.6 * progress);
    }

    // Reward pairable half-capacity residuals.
    if post_residual as f64 == cap * 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual reuse potential — divisibility-aware compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(4) as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual % next_item_size == 0 && post_residual != next_item_size {
            score -= 3.0 * progress;
        }
    }

    // Penalize residuals in a "dead zone".
    if post_residual > 12 && next_item_size > post_residual
        && (next_item_size as f64) < mean_residual * 1.5 {
        score += 3.0 * progress;
    }

    // Stranding residuals that no plausible future item can use.
    if bin_residual < bin_capacity && post_residual > 0 {
        let typical = if mean_residual > 1.0 { mean_residual } else { 10.0 };
        if (post_residual as f64) < typical * 0.6 && post_residual > 6 {
            score += 1.5 * (1.0 - post_residual as f64 / (typical * 0.6)) * (0.5 + progress);
        }
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += 0.35 * excess * (0.3 + 0.7 * progress);
        } else {
            score -= 0.15 * (-excess) * (1.0 - progress);
        }
        if post_residual <= 4 && progress > 0.2 {
            score -= 5.0 * (1.0 - pr / 5.0) * progress;
        }
    }

    // Common size bucket rewards.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0 * (0.5 + 0.5 * progress);
    }
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 2.5 + 1.5 * progress;
        } else if post_residual % 5 == 0 {
            score -= 1.5 * progress;
        }
    }

    // Near-miss lookahead: next item slightly exceeds residual.
    if next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(6)
        && next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / 7.0);
    }
    if next_item_size > post_residual && fitting_bins_count >= 2 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 2.0 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual != bin_capacity && next_item_size > post_residual
        && post_residual > 0 && next_item_size - post_residual <= 4 {
        let miss = (next_item_size - post_residual) as f64;
        score += (5.0 - miss) * (0.6 + 0.8 * progress);
    }

    // Pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair = item_size + next_item_size;
        if bin_residual >= pair {
            score -= 4.0 * (1.0 - (bin_residual - pair) as f64 / cap);
        }
    }

    // Multi-step chain fits.
    if next_item_size > 0 && pr >= (next_item_size * 2) as f64 {
        let rem3 = post_residual - next_item_size * 2;
        if rem3 <= 4 {
            score -= 3.5 * (1.0 - rem3 as f64 / 4.0) * (0.4 + 0.6 * progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size * 3 {
        let rem = post_residual - next_item_size * 3;
        if rem <= 6 {
            score -= 4.0 * (1.0 - rem as f64 / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mid-band awkward leftovers.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mid_band = pr > 8.0 && pr < 30.0
            && next_item_size > 0
            && (next_item_size as f64) > pr
            && (next_item_size as f64) < pr + 12.0;
        if mid_band {
            let tightness = 1.0 - (next_item_size as f64 - pr) / 12.0;
            let drift = ((pr - mean_residual).max(0.0) / 10.0).min(1.0);
            score += (1.5 + 3.0 * tightness + 2.0 * drift) * (0.35 + 0.65 * progress);
        }
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Residual-harvest triage.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let ratio = pr / mr;
        let near_mult = (ratio - ratio.round()).abs();
        if ratio >= 1.0 && near_mult <= 0.12 {
            score -= 2.2 * (1.0 - near_mult / 0.12) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        } else if ratio > 0.55 && ratio < 0.95 {
            score += 1.8 * (1.0 - (ratio - 0.55).abs() / 0.4) * (0.35 + 0.65 * progress);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Global dead-space budget pressure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let agg = mean_residual * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 6.0)).min(1.0);
        score += 3.0 * agg_frac * norm_pr * (0.4 + 0.6 * progress);
    }

    // Avoid leaving residuals just below the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall > 8.0 {
            score += 0.35 * (shortfall - 8.0).min(20.0) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // Variance-aware tightness.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size < post_residual {
            score -= 1.6 * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
        }
        let slack = bin_residual - item_size;
        if slack > 0 && (slack as f64) < mean_residual * 0.5 {
            score -= 2.0 * (1.0 - slack as f64 / (mean_residual * 0.5).max(1.0))
                * (0.3 + 0.7 * progress);
        }
    }

    // Fleet-wide residual collapse.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let agg_frac = (agg / (cap * 8.0)).min(1.0);
        let scarcity_w = 0.5 + 0.5 * agg_frac;
        if pr > mr * 1.05 && pr < mr * 1.45 {
            score += 1.4 * (1.0 - (pr - mr * 1.05) / (mr * 0.40).max(1.0)) * scarcity_w
                * (0.35 + 0.65 * progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 1.0 {
                score -= 3.0 * (1.0 - after.max(0.0)) * scarcity_w * (0.4 + 0.6 * progress);
            } else if after > mr * 1.6 {
                score += 0.8 * ((after - mr * 1.6) / mr).min(2.0) * scarcity_w * (0.4 + 0.6 * progress);
            }
        }
    }

    // Two-item lookahead compaction — exact double-harvest residuals.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.15 {
        let regular = (mean_residual - next_item_size as f64).abs() < mean_residual * 0.35;
        score -= if regular { 6.0 } else { 2.5 } * (0.5 + 0.5 * progress);
    }

    // Dead-space budget cap — penalize unharvestable waste, reward tightest residuals.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let agg = mr * open_bins_count.max(1) as f64;
        let tight = (1.0 - (agg / (cap * 10.0)).min(1.0)) * (0.5 + 0.5 * progress);
        if pr > mr * 2.0 {
            score += 1.1 * ((pr - mr * 2.0) / mr).min(3.0) * tight;
        }
        if pr < mr * 0.45 && pr > 0.0 && post_residual <= 8 {
            score -= 1.6 * (1.0 - pr / (mr * 0.45)) * tight;
        }
    }

    // NEW (gen 39): residual-heterogeneity compaction — when mean residual is small
    // (tight fleet), extra-reward near-zero post residuals to squeeze the last bins.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mrn = mean_residual / cap;
        if mrn < 0.08 {
            if post_residual <= 5 {
                score -= 3.5 * (1.0 - pr / 6.0) * (0.4 + 0.6 * progress);
            } else if pr > mean_residual * 2.5 {
                score += 2.0 * ((pr - mean_residual * 2.5) / mean_residual.max(1.0)).min(2.0)
                    * (0.4 + 0.6 * progress);
            }
        }
    }

    // NEW (gen 39): late-stream exact triple-fit — when two more of the next item
    // would finish the bin, escalate the reservation.
    if next_item_size > 0 && post_residual >= next_item_size * 2
        && post_residual < next_item_size * 3 && remaining < 200.0 {
        let rem = post_residual - next_item_size * 2;
        score -= 2.8 * (1.0 - rem as f64 / (next_item_size as f64).max(1.0)) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling (calibrated fresh-bin cost).
    if bin_residual == bin_capacity {
        let large_item = fill > 0.6;
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_item_size > 0 && next_large {
                fresh_cost -= 14.0;
            }
        }
        if large_item {
            fresh_cost += 4.0;
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        if mean_residual > 0.35 * cap {
            fresh_cost += 6.0 * (mean_residual / cap - 0.35);
        }
        if mean_residual > 0.25 * cap && fitting_bins_count >= 2 {
            fresh_cost -= 8.0 * (mean_residual / cap - 0.25);
        }
        fresh_cost += 8.0 * progress;
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 2 && progress > 0.5 && norm_pr > 0.25 {
            fresh_cost -= 5.0 * (norm_pr - 0.25) * 8.0 * progress;
        }
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fill > 0.5 && progress > 0.6 {
            fresh_cost -= 6.0 * (fill - 0.5) * (progress - 0.6) * 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if next_item_size as f64 > mean_residual * 2.0 && next_large && fitting_bins_count >= 2 {
            fresh_cost -= 6.0;
        }
        if fitting_bins_count >= 3 && mean_residual < 15.0 {
            fresh_cost += 5.0;
        }
        if fitting_bins_count >= 2 && norm_pr > 0.18 && mean_residual < 10.0 {
            fresh_cost -= 4.0 * (norm_pr - 0.18) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && norm_pr < 0.08 && fitting_bins_count >= 1 {
            fresh_cost += 10.0;
        }
        if fitting_bins_count >= 1 && norm_pr > mean_residual / cap * 1.2 {
            fresh_cost -= 5.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr > 0.15 && fill < 0.4 {
            fresh_cost -= 6.0 * (norm_pr - 0.15) * 10.0 * (1.0 - fill * 2.0);
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.3
            && next_item_size > 0 {
            fresh_cost -= 3.0 * ((next_item_size as f64 - mean_residual * 1.3) / cap) * 20.0;
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual && post_residual > 6 {
            fresh_cost -= 2.5 * (1.0 - (next_item_size - post_residual) as f64 / cap) * progress;
        }
        if remaining < 12.0 && fitting_bins_count >= 1 {
            fresh_cost += 8.0 * (1.0 - remaining / 12.0);
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            fresh_cost += 5.0 + 4.0 * (1.0 - item_size as f64 / (mean_residual * 0.8).max(1.0));
        }
        if fill > 0.7 && fitting_bins_count >= 2 {
            fresh_cost -= 4.0 * (fill - 0.7) * 10.0 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= item_size + next_item_size {
            fresh_cost += 4.0 + 3.0 * progress;
        }
        if remaining < 30.0 && fitting_bins_count >= 1 && fill < 0.85 {
            fresh_cost += 4.0 * (1.0 - remaining / 30.0) * (1.0 - fill);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && mean_residual > 4.0 {
            fresh_cost += 0.35 * (mean_residual - 4.0) * (progress - 0.3) * 2.0;
        }
        if fitting_bins_count >= 1 && next_item_size as f64 > 0.75 * cap {
            fresh_cost -= 5.0;
        }
        if fitting_bins_count >= 1 && post_residual > 0 {
            if post_residual <= 2 {
                fresh_cost += 12.0;
            } else if next_item_size > 0 && post_residual % next_item_size == 0 {
                fresh_cost += 8.0 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual > 0
            && next_item_size > post_residual
            && pr > mean_residual * 1.4 {
            let e = pr - mean_residual * 1.4;
            fresh_cost -= 2.0 * e * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && post_residual <= 4 && fill > 0.5 {
            fresh_cost += 10.0 * (1.0 - pr / 5.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > post_residual
            && next_item_size - post_residual <= 4
            && pr > mean_residual {
            fresh_cost -= 3.0 * (1.0 - (next_item_size - post_residual) as f64 / 5.0)
                * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 {
                fresh_cost += 3.0 * (k.min(4) as f64) * (0.3 + 0.7 * progress);
            }
        }
        if fitting_bins_count >= 1 && post_residual >= 10 && post_residual <= 20
            && next_item_size > post_residual
            && pr > mean_residual * 1.1 {
            fresh_cost -= 2.5 + 0.15 * (post_residual - 10) as f64 * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && post_residual <= 6 {
            fresh_cost += 6.0 * (1.0 - pr / 7.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Fresh-bin surcharge when an open bin would be left nearly full.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 2 {
            fresh_cost += 6.0 * (1.0 - progress);
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Item-size vs. mean-residual fresh gate.
        if fitting_bins_count >= 1 {
            let ratio = item_size as f64 / mean_residual.max(1.0);
            if ratio > 1.8 && fill > 0.45 {
                fresh_cost -= 2.5 * ((ratio - 1.8).min(3.0)) * (0.4 + 0.6 * progress);
            } else if ratio < 0.6 {
                fresh_cost += 3.0 * (0.6 - ratio) * 5.0 * (0.5 + 0.5 * progress);
            }
        }
        // Stranded-capacity fresh-bin gate.
        if fitting_bins_count >= 1 {
            let best_pr = pr;
            if best_pr > mean_residual.max(1.0) * 1.6 && fill > 0.55 {
                fresh_cost -= 3.0 * (best_pr - mean_residual.max(1.0) * 1.6).min(10.0)
                    * (0.4 + 0.6 * progress);
            } else if best_pr <= 2.0 {
                fresh_cost += 4.0 * (1.0 - best_pr / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin gate on aggregate open-bin slack.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Discourage fresh bins when the current item could finish an open bin.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin residual-drift gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn > 0.12 && fill > 0.4 {
                fresh_cost -= 4.0 * (mrn - 0.12) * 12.0 * (0.4 + 0.6 * progress);
            } else if mrn < 0.06 && fill < 0.7 {
                fresh_cost += 3.0 * (0.06 - mrn) * 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin dead-space escape valve.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            if pr > mr * 2.2 && fill > 0.35 {
                fresh_cost -= 2.5 * ((pr - mr * 2.2) / mr).min(3.0) * (0.4 + 0.6 * progress);
            }
            if pr <= mr * 0.5 {
                fresh_cost += 3.0 * (1.0 - pr / (mr * 0.5).max(1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // Fresh-bin exact-fit lockout — if any open bin would be
        // filled to within 2 units, opening a fresh bin is strongly penalized.
        if fitting_bins_count >= 1 && post_residual <= 2 {
            fresh_cost += 9.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
        }
        // Fresh-bin cheapening when item + next item would exactly
        // fill a fresh bin (perfect two-item packing) and no open bin pairs well.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= cap * 0.98
            && fitting_bins_count >= 1
            && post_residual as f64 > cap - (item_size + next_item_size) as f64 {
            fresh_cost -= 7.0;
        }
        // NEW (gen 39): fresh-bin gate on post-residual harvestability by the
        // *mean* fleet residual — if the leftover after placing here is within a
        // small window of mean_residual, prefer the open bin strongly.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            let dev = (pr - mr).abs();
            if dev <= 3.0 {
                fresh_cost += 4.5 * (1.0 - dev / 3.0) * (0.4 + 0.6 * progress);
            }
        }
        // NEW (gen 39): mid-stream fresh-bin brake — during the bulk of the
        // stream, opening bins for medium items wastes capacity; only allow it
        // for genuinely large items or when no reasonable alternative exists.
        if fitting_bins_count >= 1 && progress > 0.35 && progress < 0.85
            && fill < 0.55 && mean_residual > item_size as f64 * 0.6 {
            fresh_cost += 5.0 * (0.55 - fill) * 10.0 * (0.5 + 0.5 * progress);
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: quadratic tight-fit with progress sharpening.
    let mut score = norm_pr * norm_pr * (2.0 + 5.0 * progress) + norm_pr * (1.0 - progress);

    // Tiered dead-space handling (borrowed from best heuristic).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual < 6 {
        score -= 14.0;
    } else if post_residual < 14 {
        score += 10.0 - norm_pr * 20.0;
    } else if norm_pr < 0.10 {
        score += 6.0 * (0.10 - norm_pr) * 10.0;
    }

    // Exact-fill anticipation.
    if item_size == bin_residual && bin_residual < bin_capacity {
        score -= 85.0;
    }
    if bin_residual > item_size && bin_residual - item_size <= 3 && bin_residual < bin_capacity {
        score -= 16.0 - 4.0 * (bin_residual - item_size) as f64;
    }

    // Polynomial coupling between post_residual and progress.
    let coupling = (1.0 + progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 4.0 * coupling;
    score -= 2.5 * fill * (1.0 - fill);

    // Lookahead: chained-fill quality with divisibility awareness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            let chain_fill = next_item_size as f64 / pr;
            if rem == 0 {
                score -= 22.0 + 6.0 * chain_fill;
            } else if rem % 10 == 0 {
                score -= 15.0 + 5.0 * chain_fill;
            } else if rem < 4 {
                score += 10.0;
            } else {
                score -= 6.0 + 5.0 * chain_fill * (1.0 - progress);
            }
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            let dead = norm_pr < 0.12 && (next_item_size as f64) > pr * 2.0;
            score += norm_pr * 14.0 * if dead { 2.5 } else { 1.0 };
            score += 0.10 * pr;
        }
        let nr = next_item_size as f64;
        if nr > 0.0 && nr < pr && pr - nr <= 6.0 {
            score -= 4.5 * (1.0 - (pr - nr) / 6.0) * (1.0 - progress);
        }
        if post_residual >= next_item_size {
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / cap) * progress;
        }
        if nr > 0.0 && pr >= nr * 2.0 && pr - nr * 2.0 <= 4.0 {
            score -= 5.0 * (1.0 - (pr - nr * 2.0) / 4.0) * (0.5 + 0.5 * progress);
        }
    }

    // Pair-completion bonus.
    if next_item_size == item_size && post_residual == item_size {
        score -= 8.0;
    }

    // Soft deviation from mean residual.
    score += 0.20 * (mean_residual - pr).abs() / cap;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 11.0 * progress;
    }

    // Residual-band gap shaping.
    if bin_residual >= item_size && bin_residual < bin_capacity {
        let gap = (bin_residual - item_size) as f64;
        score += 9.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        if gap <= 12.0 {
            score -= 3.5 * (1.0 - gap / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Consolidation pressure.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.2 * norm_pr;
    }
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.2 * (open_bins_count.min(24) as f64).ln() * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    }

    // Fill-depth momentum — prefer absorbing items into the deepest bins.
    if bin_residual != bin_capacity {
        let depth = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * depth * depth * (0.4 + 0.6 * progress);
        score -= 4.0 * depth * depth * depth * progress * progress;
    }

    // Next-item sink reservation.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < next_item_size + 6 && fitting_bins_count >= 1 {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / 6.0;
        score -= 5.0 * tight * (1.0 + 0.5 / fitting_bins_count as f64);
    }

    // Dead-space liquidity gate.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        if pr <= mr * 0.6 {
            score -= 2.0 * (1.0 - pr / (mr * 0.6)) * (0.3 + 0.7 * progress);
        } else if pr > mr * 0.85 && pr < mr * 1.0 {
            score += 1.5 * (1.0 - (pr - mr * 0.85) / (mr * 0.15).max(1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Dual-lookahead fragmentation guard.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let mean_fits = pr >= mr * 0.9;
        if !next_fits && !mean_fits {
            let stranded_frac = (pr - mr * 0.9) / cap;
            score += 10.0 * stranded_frac * (0.4 + 0.6 * progress) * cap * 0.15;
        } else if next_fits {
            let chain_left = pr - next_item_size as f64;
            if (chain_left - mr).abs() <= 3.0 {
                score -= 4.0 * (1.0 - (chain_left - mr).abs() / 3.0) * (0.3 + 0.7 * progress);
            }
            if chain_left < 2.0 {
                score -= 5.0 * (1.0 - chain_left / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Compaction pressure term.
    if next_item_size > 0 && post_residual > 0 {
        let d = (pr - next_item_size as f64).abs();
        if d <= 10.0 {
            score -= 1.8 * (1.0 - d / 10.0) * progress * (1.0 - norm_pr);
        }
    }

    // Late-stream exact-fit escalation.
    if remaining < 80.0 && bin_residual != bin_capacity {
        let scarcity = 1.0 - remaining / 80.0;
        if post_residual == 0 {
            score -= 14.0 * scarcity;
        } else if post_residual <= 6 {
            score -= 4.5 * (1.0 - pr / 7.0) * scarcity;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 3.0 * (1.0 - rem as f64 / 6.0) * scarcity;
            }
        }
    }

    // Dead-space-ratio targeted compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let mr = mean_residual.max(1.0);
        let dev = (pr - mr) / mr;
        if dev < -0.25 {
            score += 2.8 * (-dev - 0.25).min(1.5) * (0.35 + 0.65 * progress);
        } else if dev > -0.10 && dev < 0.10 {
            score -= 2.4 * (1.0 - dev.abs() / 0.10) * (0.3 + 0.7 * progress);
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.18 && next_item_size as f64 > pr {
            score += 3.2 * (dead_frac - 0.18) * (0.4 + 0.6 * progress) * cap * 0.5;
        } else if dead_frac <= 0.04 {
            score -= 3.0 * (1.0 - dead_frac / 0.04) * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate handling (calibrated fresh-bin cost, mutated).
    if bin_residual == bin_capacity {
        let next_large = next_item_size as f64 / cap > 0.5;
        let mut fresh_cost = 38.0
            + 12.0 * (fitting_bins_count.min(6) as f64)
            - 12.0 * (1.0 - progress)
            + fill * 18.0;
        if fitting_bins_count == 0 {
            fresh_cost -= 30.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count == 1 {
            fresh_cost -= 10.0;
            if next_large {
                fresh_cost -= 14.0;
            }
        }
        if next_large {
            fresh_cost += 6.0;
        }
        if fitting_bins_count >= 1 && mean_residual < 8.0 {
            fresh_cost += 14.0;
        }
        fresh_cost += 8.0 * progress;
        if progress < 0.2 && fitting_bins_count >= 1 {
            fresh_cost += 6.0 * (0.2 - progress) * 5.0;
        }
        if fill > 0.9 {
            fresh_cost -= 9.0 * (fill - 0.9) * 10.0;
        }
        if fitting_bins_count >= 2 && mean_residual > 0.4 * cap {
            fresh_cost -= 10.0;
        }
        if fitting_bins_count >= 1 && post_residual > 15 && post_residual < next_item_size {
            fresh_cost -= 7.0;
        }
        if fitting_bins_count >= 1 && norm_pr > 0.3 && progress > 0.3 {
            fresh_cost -= 4.0 * (norm_pr - 0.3) * 10.0;
        }
        if remaining < 20.0 && fitting_bins_count >= 1 {
            fresh_cost -= 3.0 * (1.0 - remaining / 20.0);
        }
        if fitting_bins_count >= 1 && norm_pr <= 3.0 / cap {
            fresh_cost += 16.0;
        }
        // Fresh-bin surcharge tied to remaining scarcity.
        if fitting_bins_count >= 1 && remaining < 60.0 {
            let scarcity = 1.0 - remaining / 60.0;
            let rescue = fill > 0.85 || (next_item_size as f64 > 0.7 * cap && fill > 0.5);
            if !rescue {
                fresh_cost += 14.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
            } else {
                fresh_cost -= 4.0 * scarcity;
            }
        }
        // Discourage fresh bins when the current item would finish an open bin.
        if fitting_bins_count >= 1 && post_residual == 0 {
            fresh_cost += 10.0 + 6.0 * progress;
        }
        // Fresh-bin exact-fit lockout: near-perfect fits beat opening a bin.
        if fitting_bins_count >= 1 && post_residual <= 2 {
            fresh_cost += 9.0 * (1.0 - pr / 3.0) * (0.5 + 0.5 * progress);
        }
        // Cheapen fresh bin when item + next item would exactly fill it.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= cap * 0.98
            && fitting_bins_count >= 1
            && pr > cap - (item_size + next_item_size) as f64 {
            fresh_cost -= 7.0;
        }
        // Mean-residual-aware fresh-bin gate.
        if fitting_bins_count >= 1 {
            let mrn = mean_residual / cap;
            if mrn < 0.05 {
                fresh_cost += 10.0 * (0.05 - mrn) * 20.0 * (0.5 + 0.5 * progress);
            } else if mrn > 0.20 && fill < 0.5 {
                fresh_cost -= 6.0 * (mrn - 0.20) * 20.0;
            }
        }
        // Harvestability gate.
        if fitting_bins_count >= 1 {
            let mr = mean_residual.max(1.0);
            let ratio = pr / mr;
            let near_mult = (ratio - ratio.round()).abs();
            if ratio >= 1.0 && near_mult <= 0.12 {
                fresh_cost += 3.5 * (1.0 - near_mult / 0.12) * (0.4 + 0.6 * progress);
            } else if ratio > 0.6 && ratio < 0.95 {
                fresh_cost -= 2.5 * (1.0 - (ratio - 0.6).abs() / 0.35) * (0.4 + 0.6 * progress);
            }
        }
        // Aggregate-slack gate.
        if fitting_bins_count >= 1 {
            let agg = mean_residual * open_bins_count.max(1) as f64;
            let agg_frac = (agg / (cap * 8.0)).min(1.0);
            if agg_frac > 0.5 && fill > 0.5 {
                fresh_cost -= 5.0 * (agg_frac - 0.5) * 2.0 * (0.4 + 0.6 * progress);
            } else if agg_frac < 0.25 {
                fresh_cost += 4.0 * (0.25 - agg_frac) * 4.0 * (0.5 + 0.5 * progress);
            }
        }
        // Chain-completion gate.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                fresh_cost += 9.0 + 5.0 * progress;
            } else if post_residual > 0 && post_residual < next_item_size
                && next_item_size - post_residual > 10 {
                fresh_cost -= 2.0 * (0.4 + 0.6 * progress);
            }
        }
        // Dead-space escape valve.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            if pr > mr * 2.2 && fill > 0.35 {
                fresh_cost -= 2.5 * ((pr - mr * 2.2) / mr).min(3.0) * (0.4 + 0.6 * progress);
            }
            if pr <= mr * 0.5 {
                fresh_cost += 3.0 * (1.0 - pr / (mr * 0.5).max(1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // GEN 38 mutation: residual-homogeneity fresh gate — if post residual of
        // the best open fit aligns with fleet mean, keep compaction; else open.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let mr = mean_residual.max(1.0);
            let hom = (pr - mr).abs() / mr;
            if hom < 0.15 {
                fresh_cost += 5.0 * (1.0 - hom / 0.15) * (0.5 + 0.5 * progress);
            } else if hom > 0.6 && fill < 0.75 {
                fresh_cost -= 3.0 * ((hom - 0.6).min(1.5)) * (0.4 + 0.6 * progress);
            }
        }
        // GEN 38 mutation: two-step chain preservation — if placing here leaves
        // room for next item AND a mean-sized follow-up, favor the open bin.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let mr = mean_residual.max(1.0);
            let after1 = pr - next_item_size as f64;
            if after1 >= mr * 0.9 {
                fresh_cost += 4.0 * (1.0 - (after1 - mr * 0.9).min(6.0) / 6.0) * (0.4 + 0.6 * progress);
            }
        }
        score += fresh_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;
